// Original explanations and synthetic practice; private source inventory is not distributed.
const S=String.raw;
const sec=(id,title,html)=>({id,title,html});
const number=(id,prompt,answer,explanation,tolerance=.01)=>({id,prompt,type:'number',answer,tolerance,explanation});
const choice=(id,prompt,answer,choices,explanation)=>({id,prompt,type:'choice',answer,choices:choices.map(([value,label])=>({value,label})),explanation});
export const lessons=[
{
 id:'week01-customer',week:1,title:'Клиентский путь и показатели магазина',description:'Свяжем устройство ретейла, ценность для покупателя и измеримые точки потерь.',minutes:25,visual:'product',goals:['Различать продукт, канал и клиентский путь','Посчитать конверсию, NPS, CSAT и продажи на площадь'],
 sections:[
 sec('question','Где покупатель теряет ценность?',S`<p>Ретейлер покупает товары у поставщиков и продаёт их конечному покупателю. Его продуктом оказывается не только пачка товара, но и доступный ассортимент, расположение магазина, понятная цена, доставка и обслуживание. Производитель FMCG выпускает товары повседневного спроса; ретейлер решает, какие из них предложить на своей полке. Собственная торговая марка позволяет сети участвовать ещё и в создании продукта.</p><p>Клиентский путь, CJM, описывает действия покупателя до, во время и после покупки. Для каждого этапа нужны цель человека, его действие, контакт с компанией, затруднение и наблюдаемый результат. «Улучшить приложение» слишком расплывчато; «сократить ошибки адреса на этапе оформления» связывает действие с конкретной потерей клиентов.</p>`),
 sec('data','Пример: маленький магазин с доставкой',S`<p>Все числа далее учебные. За неделю 2 000 человек открыли каталог, 600 положили товар в корзину, 240 оплатили заказ, 216 получили его без отмены. Покупатель ищет быстрый ужин: на этапе поиска ему нужны фильтры, при оплате — полная стоимость, после заказа — точное время доставки.</p><div class="table-wrap"><table><thead><tr><th>Этап</th><th>Количество</th><th>Что проверяем</th></tr></thead><tbody><tr><td>Каталог</td><td>2 000</td><td>Наличие и понятный выбор</td></tr><tr><td>Корзина</td><td>600</td><td>Цена доставки и минимальная сумма</td></tr><tr><td>Оплата</td><td>240</td><td>Успешность платежа</td></tr><tr><td>Получение</td><td>216</td><td>Отмены, сроки, качество</td></tr></tbody></table></div><p>Переходы равны 30%, 40% и 90%. Сквозная конверсия — 216 / 2 000 = 10,8%. Перемножение 0,30 × 0,40 × 0,90 даёт то же число. В знаменателе каждого шага находятся люди на предыдущем этапе, а не все посетители.</p>`),
 sec('metrics','Удовлетворённость: две разные задачи',S`<p>NPS отвечает на вопрос о готовности рекомендовать. На обычной шкале 0–10 промоутеры поставили 9–10, критики — 0–6, нейтральные — 7–8. При 50 промоутерах, 20 критиках и 30 нейтральных из 100 ответивших NPS = 50% − 20% = 30 процентных пунктов. Нейтральных нельзя выбросить из знаменателя.</p><div data-math="NPS=\frac{N_{9,10}-N_{0,\ldots,6}}{N_{\mathrm{all}}}\cdot100"></div><p>CSAT измеряет долю удовлетворённых в конкретном опросе. Порог надо задать заранее: если положительными считаются 7–10 и таких ответов 76 из 100, CSAT = 76%. У NPS и CSAT могут быть одинаковые исходные оценки, но разные пороги и смысл. Показатель по транзакциям и показатель по уникальным людям тоже различаются: часто покупающий клиент иначе повлияет на итог.</p>`),
 sec('retail','Ассортимент, площадь и формат',S`<p>SKU — конкретная товарная позиция, товарная линия — группа близких позиций, product mix — весь ассортимент. Его ширина показывает число линий, глубина — варианты внутри линии. Узкая полка дискаунтера и широкий выбор супермаркета обслуживают разные задачи клиента; оценивать их одинаковым набором товаров неправильно.</p><p>Пусть категория напитков продала на 360 000 ₽ за месяц и занимает 30 м². Продажи на площадь, SPSM, равны 12 000 ₽/м² за месяц. Средний чек при выручке 900 000 ₽ и 1 500 чеках равен 600 ₽. Продажи на площадь не равны прибыли на площадь: у категории с большим оборотом могут быть низкая маржа, порча и дорогая выкладка.</p><p>В Excel сначала убедись, что строка — товар в чеке, целый чек или клиент. Для среднего чека дели суммарную выручку на число уникальных чеков. Для частоты покупок — уникальные чеки на уникальных покупателей. Сумма покупателей отдельных категорий обычно больше числа покупателей магазина, потому что один человек покупает в нескольких категориях.</p>`),
 sec('decision','От метрики к инициативе',S`<p>Если при получении отменяется 10% оплаченных заказов, гипотеза про красивую главную страницу не объясняет эту потерю. Сначала разбери причины отмен: отсутствие товара, опоздание, неверный адрес. Затем сформулируй изменение, ожидаемую метрику, период проверки и риск. Например, резервирование остатков может снизить отмены, но временно уменьшит доступный ассортимент другим клиентам.</p><p>Не переносим автоматически деньги с категории с низким SPSM: она может дополнять корзину и удерживать покупателей. Сравни продажи, валовую прибыль, оборачиваемость, роль категории и удовлетворённость. Для сравнения периодов нужны одинаковые длительность, сезонность и правила учёта.</p>`)
 ],practice:[number('nps','Из 200 ответов 90 — оценки 9–10, 50 — оценки 0–6. Чему равен NPS в процентных пунктах?',20,'(90 − 50) / 200 × 100 = 20. Оставшиеся 60 нейтральных входят в знаменатель.'),number('area','Выручка категории за месяц 480 000 ₽, площадь 40 м². Найди SPSM, ₽/м² за месяц.',12000,'480 000 / 40 = 12 000 ₽/м² за месяц. Это показатель выручки, ещё не прибыли.')],sourceNote:'Темы недели 1: ретейл, продукт и клиентский опыт.'
},
{
 id:'week01-unit-economics',week:1,title:'Юнит-экономика: от чека к CLTV',description:'Соберём выручку на клиента, маржу, отток, стоимость привлечения и прибыль юнита.',minutes:30,visual:'product',goals:['Различать чек, частоту и выручку на клиента','Оценить CLTV и вклад клиента с явными предпосылками'],
 sections:[
 sec('unit','Сначала выбери единицу анализа',S`<p>Юнит — единица, для которой проверяется экономика: заказ, товар, покупатель или подписчик. Нельзя вычесть CAC клиента из прибыли одного товара и объявить результат пожизненной прибыльностью. Зафиксируй единицу, период, валюту и то, какие расходы включены.</p><p>Маржа в деньгах равна цене минус выбранные затраты. Маржинальность делит эту разницу на цену; процентная наценка — на себестоимость. При цене 800 ₽ и себестоимости 500 ₽ разница 300 ₽, маржинальность 37,5%, наценка 60%. Если в условии «наценка» дана в рублях, это просто разница 300 ₽.</p>`),
 sec('table','Собираем метрики из операций',S`<p>У учебного магазина за месяц 1 000 покупателей сделали 1 500 заказов на 1 800 000 ₽. Средний чек = 1 800 000 / 1 500 = 1 200 ₽. Частота = 1 500 / 1 000 = 1,5 заказа на клиента. ARPC, выручка на покупателя за месяц, = 1 200 × 1,5 = 1 800 ₽.</p><div data-math="ARPC=\frac{Revenue}{Customers}=\frac{Revenue}{Orders}\cdot\frac{Orders}{Customers}"></div><p>Для категории делай ту же цепочку на её клиентах и чеках. Если один чек содержит несколько товаров категории, не считай каждую строку отдельным заказом. Для общей метрики магазина заново считай уникальные идентификаторы; среднее средних чеков категорий не является общим средним чеком.</p>`),
 sec('lifetime','Почему срок жизни связан с оттоком',S`<p>Предположим, каждый активный клиент с одной и той же вероятностью 25% уходит в конце месяца, а до ухода приносит одинаковый месячный вклад. Тогда ожидаемое число активных месяцев равно 1 / 0,25 = 4. В этой модели клиент участвует уже в первом месяце. Retention = 1 − churn = 75%; делить на retention для срока жизни нельзя.</p><div data-math="Lifetime=\frac1{c},\qquad CLTV=ARPC\cdot m\cdot\frac1c"></div><p>Здесь c — месячный отток, m — доля валовой маржи. При m = 40% CLTV = 1 800 × 0,40 × 4 = 2 880 ₽. Это ожидаемая валовая прибыль клиента до расходов на привлечение, без дисконтирования и без дополнительных расходов на обслуживание. Название LTV иногда используют и для выручки: всегда указывай, что именно посчитано.</p>`),
 sec('cac','Привлечение и вклад',S`<p>Маркетинг и продажи потратили 180 000 ₽ и привели 300 новых платящих покупателей. CAC = 600 ₽/клиента. Contribution Profit клиента в принятой модели = CLTV − CAC = 2 280 ₽. Отношение CLTV/CAC = 4,8. Это не гарантия успеха: компании ещё нужны деньги на постоянные расходы и на разрыв между оплатой рекламы и получением будущей прибыли.</p><p>CPU, цена привлечения пользователя, может относиться к регистрации, а CAC — к первой покупке. Если CPU = 120 ₽, а покупают 20% зарегистрировавшихся, CAC = 120 / 0,20 = 600 ₽. Добавь расходы отдела продаж, если исходный CPU включает только рекламу. Знаменатель CAC — новые привлечённые клиенты, а не все покупатели периода.</p>`),
 sec('growth','Темп роста и сопоставимая база',S`<p>Если месячная выручка выросла с 800 000 до 920 000 ₽, абсолютный прирост 120 000 ₽, относительный = 120 000 / 800 000 = 15%. Темп роста как отношение нового к старому равен 115%; темп прироста — 15%. Называй выбранное определение, чтобы число 115% не выглядело увеличением более чем вдвое.</p><div data-math="CAGR=\left(\frac{V_n}{V_0}\right)^{1/n}-1"></div><p>При росте с 100 до 144 за два года CAGR = 20% годовых, поскольку 100 × 1,2² = 144. Это постоянный эквивалентный темп, а не описание каждого фактического года. Начальное значение должно быть положительным для обычной интерпретации. LFL, like-for-like, сравнивает сопоставимые магазины и периоды: открытие новых точек надо отделять от роста продаж прежних.</p>`),
 sec('limits','Когда простая модель перестаёт работать' ,S`<p>При нулевом оттоке формула 1/c не даёт конечной оценки: это сигнал перейти к ограниченному горизонту, а не объявить бесконечную ценность. При меняющихся по месяцам удержании и расходах строй когорту: для каждого месяца найди вероятность остаться, вклад активного клиента и при необходимости дисконтируй поток.</p><p>Сравнение каналов требует одинакового периода и состава затрат. Большая CLTV может сочетаться с ещё большим CAC. Рост выручки, вызванный скидкой, может снизить валовую прибыль. В выводе называй главный драйвер: чек, частота, маржа или отток, а также предел применимости модели.</p>`)
 ],practice:[number('cltv','ARPC = 1 500 ₽/месяц, валовая маржа 30%, месячный churn = 20%. CLTV в принятой стационарной модели, ₽?',2250,'Месячный вклад 1 500 × 0,30 = 450 ₽. Lifetime = 1 / 0,20 = 5 месяцев. CLTV = 2 250 ₽.'),number('contribution','Для клиента CLTV = 2 250 ₽, CAC = 750 ₽. Найди Contribution Profit, ₽.',1500,'2 250 − 750 = 1 500 ₽ до дополнительных неучтённых расходов.')],sourceNote:'Темы недели 1 и практики блока 1: метрики клиента и юнит-экономика.'
},
{
 id:'week02-marketing',week:2,title:'Маркетинг: сегмент, задача клиента и канал',description:'Переведём знания о клиенте в проверяемый выбор предложения и рекламы.',minutes:25,visual:'market',goals:['Сформулировать сегмент и Jobs to be Done','Сравнить CPC, CPM и CPA на одной воронке'],
 sections:[
 sec('segment','Кому и в какой ситуации нужен продукт?',S`<p>Сегментация делит клиентов на группы со сходной потребностью или поведением. Возраст сам по себе не объясняет выбор. Один студент покупает продукты на неделю с минимальной ценой, другой — ужин за 20 минут перед занятием. Их ограничения по времени и размеру корзины подсказывают разные предложения.</p><p>Персона описывает типичного пользователя и его контекст. Jobs to be Done формулирует задачу: «Когда возвращаюсь поздно, хочу получить готовый ужин, чтобы поесть без готовки». Интервью Customer Development проверяет, случается ли такая ситуация на самом деле, как человек решает её сейчас и за что уже платит. Вопрос «вам понравилась бы наша идея?» даёт слабое доказательство.</p>`),
 sec('channels','Не смешивай привлечение и доставку',S`<p>Маркетинговый канал приводит внимание: поиск, социальная сеть, рекомендации, наружная реклама. Канал продаж принимает заказ: приложение, магазин, маркетплейс. Дистрибуция доставляет товар до точки продажи или покупателя. Одна компания использует несколько каналов, но измерять их надо по одинаковому целевому действию.</p><p>Массовая реклама поддерживает узнаваемость; таргетированная активность обращается к выбранной аудитории. Атрибуция покупок к рекламе не равна причинному приросту: покупатель мог бы прийти и без неё. Для сильного вывода нужна сравнимая контрольная группа либо честно оговорённое ограничение оценки.</p>`),
 sec('funnel','Один пример для трёх моделей оплаты',S`<p>Синтетическая кампания получила 100 000 показов, 2 000 кликов и 100 новых покупателей. CTR = 2%, конверсия клика в покупателя = 5%, сквозная конверсия = 0,1%. Пусть CPC = 8 ₽ за клик, CPM = 180 ₽ за тысячу показов, CPA = 170 ₽ за нового покупателя.</p><div class="table-wrap"><table><thead><tr><th>Модель</th><th>Расход</th><th>CAC</th></tr></thead><tbody><tr><td>CPC</td><td>2 000 × 8 = 16 000 ₽</td><td>160 ₽</td></tr><tr><td>CPM</td><td>100 000 / 1 000 × 180 = 18 000 ₽</td><td>180 ₽</td></tr><tr><td>CPA</td><td>100 × 170 = 17 000 ₽</td><td>170 ₽</td></tr></tbody></table></div><p>При этих одинаковых количестве и качестве покупателей CPC дешевле. Если CPA оплачивает установку, а не покупку, такое сравнение неверно: надо учесть последующую конверсию.</p>`),
 sec('formulas','Проверка размерностей и чувствительности',S`<div data-math="CAC_{CPC}=\frac{CPC}{CR_{click\to buyer}},\qquad CAC_{CPM}=\frac{CPM}{1000\cdot CTR\cdot CR_{click\to buyer}}"></div><p>CR и CTR подставляются долями, например 0,05, а не числом 5. Если конверсия клика падает с 5% до 4%, CAC в модели CPC вырастает с 160 до 200 ₽. CPM тоже зависит от кликабельности: низкий CTR делает показы дорогими в пересчёте на реального покупателя.</p><p>В таблице выдели входные ячейки: показы, клики, покупатели, тариф. Расходы и CAC рассчитывай формулами. Дополнительные агентские и производственные расходы прибавляй одинаково для сравниваемых вариантов. Если покупатели отличаются по удержанию, сравни ещё их CLTV и вклад.</p>`),
 sec('custdev','Как принять решение о канале',S`<p>Сначала сформулируй сегмент и обещание, затем выбери наблюдаемое действие. На тесте проверь не только стоимость, но и долю новых клиентов, возвраты, средний чек, качество заявок и последующее удержание. Раздели этапы поиска проблемы, проверки платёжного спроса и масштабирования: дорогая реклама не исправляет отсутствие нужной клиенту ценности.</p><p>Для FMCG важно также, представлен ли товар там, куда приведён спрос. Если реклама сработала, но товара нет на полке, маркетинг и операции оптимизируют разные части одной цепочки. Вывод должен содержать бюджет теста, метрику успеха и условие остановки.</p>`)
 ],practice:[number('cpc','Клик стоит 12 ₽, 4% кликнувших становятся покупателями. CAC без других расходов, ₽?',300,'12 / 0,04 = 300 ₽ за покупателя.'),number('cpm','CPM = 240 ₽, CTR = 3%, конверсия клика в покупку = 4%. CAC, ₽?',200,'240 / (1 000 × 0,03 × 0,04) = 200 ₽.')],sourceNote:'Темы недели 2: сегментация, Customer Development, каналы и рекламные метрики.'
},
{
 id:'week02-pricing',week:2,title:'Цена, воронка и потребительская ценность',description:'Проверим, когда скидка повышает прибыль, и как связаны удержание и повторные продажи.',minutes:27,visual:'market',goals:['Отличать рост выручки от роста прибыли','Сравнить ценовую инициативу и улучшение конверсии'],
 sections:[
 sec('price','Цена меняет сразу несколько показателей',S`<p>Цена может опираться на затраты, конкурентов и ценность для клиента. Расчёт «себестоимость плюс 20%» проверяет покрытие части расходов, но не доказывает, что покупатель согласится платить. Цена конкурента полезна только при сопоставимых качестве, упаковке, сервисе и канале.</p><p>Ценовая эластичность связывает относительное изменение количества с относительным изменением цены. Сохраняй знак: при обычном спросе рост цены снижает количество. Для двух заметно различающихся точек удобно использовать средние значения в знаменателях, то есть дуговую эластичность. Две наблюдаемые продажи сами по себе не доказывают причинный эффект цены: могли измениться сезон, реклама или наличие.</p>`),
 sec('elasticity','Проверяем скидку на оригинальных числах',S`<p>Магазин продавал 1 000 единиц по 100 ₽ при переменных затратах 60 ₽. Теперь цена 90 ₽, продажи 1 250 единиц. Выручка выросла с 100 000 до 112 500 ₽, но вклад до постоянных затрат снизился с 40 000 до 37 500 ₽.</p><div data-math="\pi=(P-v)Q-F,\qquad Q_{new}^{break-even}=\frac{(P_{old}-v)Q_{old}}{P_{new}-v}"></div><p>Чтобы сохранить прежний вклад, нужно 40 000 / 30 = 1 333,33 единицы, а для целых товаров — минимум 1 334. Данных о росте количества на 25% недостаточно, когда вклад единицы упал с 40 до 30 ₽. При неизменных постоянных затратах сравнение вкладов одновременно сравнивает и прибыль.</p>`),
 sec('elasticity-method','Эластичность: численная мера',S`<div data-math="E_{arc}=\frac{(Q_2-Q_1)/((Q_1+Q_2)/2)}{(P_2-P_1)/((P_1+P_2)/2)}"></div><p>Для перехода цены со 100 до 90 ₽ и количества с 1 000 до 1 250 относительное изменение количества к средней базе равно 250/1 125, цены — −10/95. Дуговая эластичность ≈ −2,11. Её модуль больше 1: количество реагирует относительно сильнее цены. Эластичность безразмерна; значение −2 не означает −2%.</p><p>Для малых изменений применяют локальную оценку ΔQ/Q ≈ E × ΔP/P. При E=−0,5 и росте цены на 4% ожидаемое изменение количества примерно −2%. Выручка тогда меняется в (1,04×0,98)=1,0192 раза, на 1,92%. Эластичность по доходу меняет знаменатель на доход; перекрёстная — на цену другого товара. Знак помогает отличать заменители и дополняющие товары.</p>`),
 sec('offer','Upselling, cross-selling и bundle' ,S`<p>Upselling предлагает более дорогой вариант той же задачи; cross-selling — дополняющий товар; bundle — набор. Если напиток стоил 100 ₽ и давал 40 ₽ вклада, а набор из напитка и снека продаётся за 150 ₽ при общих переменных затратах 95 ₽, вклад набора 55 ₽. Это больше на 15 ₽, но часть покупателей и без набора купила бы оба товара по полной цене. Такой перенос существующих продаж надо учитывать как каннибализацию.</p><p>Не повышай выручку на процент и не оставляй затраты автоматически прежними: добавленный товар стоит денег. Проверяй наличие, размер скидки, комиссию канала, возвраты и действительно дополнительный спрос.</p>`),
 sec('retention','Удержание и отток',S`<p>Customer Value Management управляет ценностью существующих клиентов: первым опытом, повторными покупками, персональными предложениями, возвратом ушедших. Пусть месячный отток был 25%, стал 20%. Он снизился на 5 процентных пунктов, или на 20% относительно исходного. Это разные изменения.</p><p>При месячном валовом вкладе 400 ₽ простая CLTV была 400 / 0,25 = 1 600 ₽, стала 400 / 0,20 = 2 000 ₽. Прирост 400 ₽ нужно сопоставить со стоимостью программы. NPS может сопровождать удержание, но универсальной формулы «NPS → churn» нет. Если учебное условие задаёт связь через пороги оценки, это отдельная модель, которую надо явно записать.</p>`),
 sec('interpret','Таблица решения и рисков',S`<p>Для каждой инициативы создай отдельный сценарий: прежний чек, новый чек, частота, маржа, churn, CLTV, CAC, дополнительные расходы. Сначала меняй только параметры, которые прямо изменяет инициатива. Не суммируй эффект двух взаимоисключающих инициатив и не вкладывайся дважды в одну категорию, если таково ограничение задачи.</p><p>Сочетание высокого NPS и отрицательного вклада говорит о ценности для клиента без жизнеспособной экономики. Положительный вклад при низком NPS указывает на риск удержания. Положительные оба показателя не отменяют проверки ограничений мощности и окупаемости денег во времени. Рекомендация включает предполагаемый механизм, количественный эффект и риск ошибки.</p>`)
 ],practice:[number('volume','Цена снизилась со 100 до 90 ₽, переменные затраты 60 ₽. Ранее продавали 900 шт. Сколько штук нужно для прежнего вклада?',1200,'Прежний вклад 900 × 40 = 36 000 ₽. Новый вклад единицы 30 ₽. 36 000 / 30 = 1 200 шт.'),number('pp','Churn снизился с 30% до 24%. На сколько процентных пунктов?',6,'30% − 24% = 6 процентных пунктов. Относительное снижение равно 6 / 30 = 20%.')],sourceNote:'Темы недель 2–3: ценообразование, воронка, CVM и оценка инициатив.'
},
{
 id:'week03-assortment',week:3,title:'Ассортимент и выход на маркетплейс',description:'Сравним категории, взвесим маржу и включим доставку, комиссии и возвраты.',minutes:28,visual:'market',goals:['Взвешивать маржинальность по выручке','Сравнивать товарные модели с полной стоимостью канала'],
 sections:[
 sec('question','Почему самая высокая маржа не всегда побеждает',S`<p>Компания выбирает не процент сам по себе, а результат продажи при ограничениях спроса и ресурсов. Товар с маржой 50% и выручкой 10 000 ₽ приносит 5 000 ₽; товар с маржой 20% и выручкой 100 000 ₽ — 20 000 ₽. При одинаковой базе затрат второй создаёт больше абсолютного вклада.</p><p>Сравнивая SKU, товарные линии и рынки, сначала зафиксируй цены, объёмы, переменные издержки и дополнительные постоянные расходы. При переносе продаж на другой рынок цена и объём могут измениться вместе. Условие «продадим там же всё по старой цене» требует отдельного обоснования.</p>`),
 sec('weighted','Смешанный ассортимент',S`<p>Учебный продавец продаёт 100 термокружек по 1 000 ₽ с затратами 600 ₽ и 200 контейнеров по 500 ₽ с затратами 350 ₽. Выручка обеих линий равна 100 000 ₽. Вклад кружек — 40 000 ₽, контейнеров — 30 000 ₽, общий вклад — 70 000 ₽.</p><div data-math="m_{mix}=\frac{\sum_i Q_i(P_i-v_i)}{\sum_i Q_iP_i}=\frac{70000}{200000}=35\%"></div><p>Здесь простое среднее 40% и 30% случайно тоже равно 35%, потому что выручки равны. Если объёмы поменяются, процент нужно пересчитать через суммы. Для категории в таблице применяй суммирование выручки и затрат, а не среднее процентов строк.</p>`),
 sec('fulfillment','Кто выполняет заказ?',S`<p>При FBO товар заранее хранится у оператора площадки; при FBS хранит и собирает продавец, а площадка участвует в доставке; при DBS продавец сам организует хранение и доставку. Названия тарифов могут различаться, поэтому всегда читай конкретный договор. Модель влияет на сроки, издержки и ответственность за возврат.</p><p>Цена учебного товара 2 000 ₽, закупка 900 ₽, комиссия 15% цены, доставка 180 ₽, упаковка 40 ₽. Ожидаемые расходы на возвраты 80 ₽ на проданную единицу. Вклад = 2 000 − 900 − 300 − 180 − 40 − 80 = 500 ₽, маржинальность 25%. «Закупка и доставка» без комиссии дали бы завышенный результат.</p>`),
 sec('data','Как разбирать таблицы продаж',S`<p>Определи зерно данных: строка может означать SKU, продажу, регион или заявку. Проверь валюту, налоговую базу, количество, период и пропуски. В сводной таблице можно сгруппировать товары по категориям и регионам, получить суммы количества, выручки, затрат и минимум/максимум цены.</p><p>Средняя цена сделки с учётом проданных единиц — выручка / количество. Простое среднее цен SKU отвечает другому вопросу: сколько в среднем стоит позиция из списка. «Самая популярная» категория тоже требует определения: по штукам, числу заказов или выручке. Оба ответа допустимы только с названной метрикой.</p>`),
 sec('distribution','FMCG: охват полки и наличие',S`<p>Производитель может расти через число торговых точек, число SKU в точке, скорость продаж позиции и цену. Если товар представлен в 80 магазинах из 200 целевых, числовая дистрибуция 40%. Если эта группа магазинов обеспечивает 60% продаж категории сети, взвешенная по продажам дистрибуция 60%. Для второго показателя нужны продажи категории, а не только список точек.</p><p>Ротация — скорость продажи артикула на полке за выбранный период. Отсутствие товара, OOS, прерывает продажи и может испортить вывод о спросе: нулевая продажа не обязательно означает отсутствие интереса. OTIF измеряет заказы, пришедшие вовремя и полностью; доля продаж до конца срока свежести помогает видеть потери. Объясняй инициативу через конкретный драйвер: новая точка, дополнительная позиция, наличие или скорость продаж.</p>`),
 sec('launch','Рекомендация о запуске' ,S`<p>После расчёта вклада добавь складские минимумы, расходы запуска, маркетинг, оборотный капитал и ограничение спроса. При постоянных расходах запуска 100 000 ₽ и вкладе 500 ₽ на товар нужно 200 продаж для покрытия запуска. Если ожидается лишь 120, положительная маржа единицы не спасает проект.</p><p>Финальный короткий вывод строится из трёх частей: выбранный вариант, числа, которые его поддерживают, и условия/риски. Например: тестировать одну категорию малыми партиями, поскольку вклад положителен и реалистичный спрос покрывает запуск; следить за возвратами и тарифами. Это полезнее списка несвязанных метрик.</p>`)
 ],practice:[number('marketplace','Цена 1 500 ₽, закупка 700 ₽, комиссия 20%, доставка 120 ₽, упаковка 30 ₽, ожидаемые возвраты 50 ₽. Вклад товара, ₽?',300,'Комиссия 300 ₽. 1 500 − 700 − 300 − 120 − 30 − 50 = 300 ₽.'),number('weighted','Первая линия: выручка 80 000 ₽ и вклад 32 000 ₽. Вторая: выручка 120 000 ₽ и вклад 24 000 ₽. Общая маржинальность в процентах?',28,'(32 000 + 24 000) / (80 000 + 120 000) × 100 = 28%.')],sourceNote:'Темы недели 3: ассортимент, международные продажи и модели исполнения заказов.'
},
{
 id:'week04-operations',week:4,title:'Операции: мощность и узкое место',description:'Переведём время, людей и циклы в выпуск всей цепочки и оценим эффект улучшения.',minutes:30,visual:'operations',goals:['Различать design capacity, effective capacity и actual output','Находить ограничение всей цепочки в сопоставимых единицах'],
 sections:[
 sec('chain','Цепочка создания ценности',S`<p>Операции превращают ресурсы в товар или услугу. В цепочке Портера основные действия — входящая логистика, производство, исходящая логистика, маркетинг/продажи и сервис; поддерживающие — закупки, технологии, персонал и инфраструктура. Модель нужна, чтобы найти связь между улучшением процесса и ценностью для клиента.</p><p>Показатели процесса описывают разные стороны: cycle time — время операции или прохождения заказа в явно выбранной границе; capacity — предельный выпуск за период; throughput — фактический выпуск. Уточняй, включены ли ожидание, перерывы и переналадка: быстрый отдельный станок ещё не гарантирует быстрый заказ.</p>`),
 sec('capacity','Номинальная, эффективная и фактическая мощность',S`<p>Пусть линия доступна 200 часов в месяц по календарю, 20 часов запланировано на обслуживание. Design capacity = 200 ч, effective capacity = 180 ч. Фактически отработано 153 производительных часа.</p><div data-math="Utilization=\frac{Actual}{Design}=76{,}5\%,\qquad Efficiency=\frac{Actual}{Effective}=85\%"></div><p>Знаменатели различаются. Утилизация показывает использование номинального потенциала; эффективность — использование реалистично доступного времени после плановых потерь. Если линия делает 12 заказов за производительный час, эффективная мощность 2 160 заказов. Нельзя делить часы на количество заказов и называть результат заказами в час.</p>`),
 sec('bottleneck','Минимум цепочки',S`<p>Три последовательных этапа могут обработать 120, 90 и 110 заказов в день. При одинаковом потоке и отсутствии иных ограничений вся цепочка может завершить не более 90. Узкое место — второй этап. Улучшение первого этапа до 150 не увеличивает выпуск, а может увеличить очередь перед вторым.</p><p>Если второй этап улучшить до 105, выпуск ограничится 105; после улучшения до 120 ограничением станет третий этап с 110. Фактический выпуск ещё ограничен спросом и наличием сырья: при спросе 80 нет основания продавать 105. Для параллельных одинаковых ресурсов мощности складываются; для последовательных выбирается минимум.</p>`),
 sec('cycles','Циклы, сотрудники и смешанные заказы',S`<p>Один цикл машины состоит из 4 часов работы и 1 часа калибровки. За 20 часов помещается 4 полных цикла, то есть 16 производительных часов. Если по условию работа должна заканчиваться до неполного цикла, используй округление вниз. Когда разрешена частичная работа последнего цикла, календарь надо моделировать отдельно — нельзя применять целочисленное правило молча.</p><p>Пять сотрудников по 8 часов дают 40 человеко-часов. Если заказ A требует 0,5 часа, а B — 1 час, ограничение имеет вид 0,5A + B ≤ 40. Для заказа из 30 A и 30 B нужно 45 часов: дефицит 5. Сравнивай не только мощности в «заказах», если состав заказов разный, а использование времени каждого этапа.</p>`),
 sec('improve','Как увеличивать выпуск осмысленно',S`<p>Сначала обеспечь непрерывную работу узкого места: отсутствие сырья, брак и простой на нём стоят выпуска всей цепочки. Затем оцени перераспределение людей, переналадку, сверхурочные, дополнительное оборудование или передачу заказов подрядчику. После изменения снова найди минимум.</p><p>Lean устраняет действия без ценности; 5S упорядочивает рабочее место; Kaizen означает последовательные небольшие улучшения; Poka-Yoke предотвращает ошибки конструкцией процесса. Их эффект измеряется временем, качеством и выпуском, а не самим фактом внедрения. Ускорение с ростом брака может уменьшить число годных заказов.</p>`)
 ],practice:[number('efficiency','Design = 240 ч, effective = 200 ч, actual = 170 ч. Efficiency в процентах?',85,'Efficiency = 170 / 200 × 100 = 85%. Utilization была бы 170 / 240 = 70,83%.'),number('chain','Мощности последовательных этапов 140, 100 и 125 заказов/день. Спрос 130. Максимальный выпуск, заказов/день?',100,'Минимум мощностей и спроса: min(140, 100, 125, 130) = 100.')],sourceNote:'Темы недели 4 и операционной практики: процессы, capacity и узкие места.'
},
{
 id:'week04-healthcare',week:4,title:'Экономика улучшений в здравоохранении',description:'Сравним спрос, производственную мощность и дополнительную прибыль от оборудования.',minutes:27,visual:'operations',goals:['Рассчитать эффект инициативы по дополнительным потокам','Отделять экономический анализ от качества и безопасности услуги'],
 sections:[
 sec('context','Отраслевой контекст',S`<p>В здравоохранении цепочка связывает исследование и разработку, производство, контроль качества, дистрибуцию и оказание помощи. У производителя лекарства покупатель, назначающий специалист, плательщик и пользователь могут быть разными людьми или организациями. Для рецептурного и безрецептурного продукта доступ к клиенту устроен по-разному.</p><p>Разработка включает поиск решения, доклинические и клинические исследования, регистрацию и последующее наблюдение. На ранних этапах много неудач и длительное ожидание результата. Операционный аналитик должен учитывать качество и надёжность данных; рост выпуска не является доказательством медицинской эффективности. Здесь мы считаем учебную экономику, не выбираем лечение.</p>`),
 sec('demand','Маркетинг упирается в мощность',S`<p>Учебное производство продаёт 1 000 упаковок по 500 ₽, переменные затраты 200 ₽, постоянные расходы 200 000 ₽. Прибыль = (500 − 200) × 1 000 − 200 000 = 100 000 ₽. Мощность — 1 100 упаковок. Дополнительная реклама за 40 000 ₽ создаст спрос ещё на 300 упаковок.</p><p>Без расширения можно продать только 100 дополнительных упаковок. Дополнительный вклад 100 × 300 = 30 000 ₽, после рекламы изменение прибыли −10 000 ₽. Ошибка — посчитать все 300 заказов, не проверив выпуск. Если расширение до 1 300 стоит ещё 20 000 ₽ за период, совместная инициатива даст 300 × 300 − 40 000 − 20 000 = 30 000 ₽ прироста.</p>`),
 sec('equipment','Оборудование: сравнение двух способов',S`<p>Клиника рассматривает оборудование за 3 600 000 ₽. Сейчас выполняет 120 процедур в месяц по 10 000 ₽; переменные затраты 4 000 ₽. После покупки мощность и спрос позволяют 150 процедур, переменные затраты снижаются до 3 500 ₽, дополнительные обслуживание и обучение стоят 75 000 ₽/месяц.</p><p>Старый месячный вклад 120 × 6 000 = 720 000 ₽. Новый вклад до обслуживания 150 × 6 500 = 975 000 ₽. Прирост после обслуживания 180 000 ₽. Простая окупаемость = 3 600 000 / 180 000 = 20 месяцев. Общие неизменные расходы при сравнении сокращаются, а новые включаются.</p>`),
 sec('staff','Проверка доступности ресурсов',S`<p>Для каждой процедуры могут требоваться одновременно врач, ассистенты, кабинет и оборудование. Если оборудование ускорило операцию, но не хватает времени врача или послеоперационных мест, объём не вырастет до расчётного. Для каждой профессии посчитай доступные человеко-часы и норматив на одну процедуру; затем найди минимальную пропускную способность.</p><p>Доли сотрудников применяются к числу людей, а не автоматически к рабочим часам: занятость может различаться. Не допускай «4,5 сотрудника», если люди неделимы и условие не разрешает неполную ставку. Оплата труда может быть постоянной на горизонте месяца, даже когда аналитически распределена на процедуру.</p>`),
 sec('risks','Решение не заканчивается окупаемостью',S`<p>Окупаемость игнорирует стоимость денег и потоки после возврата вложений. Проверь также NPV, срок службы, остаточную стоимость, простой, рост спроса, обучение и расходы на смену процесса. При отсутствии роста спроса пересчитай только экономию на прежнем объёме — результат может стать совсем другим.</p><p>Структура рекомендации: исходная проблема → измеримое изменение → дополнительная прибыль или поток → инвестиции → риски и условие проверки. Нельзя считать сокращённые штатные часы денежной экономией, если фактический фонд оплаты труда не меняется. Освобождённое время всё равно может иметь ценность, если позволяет обслужить дополнительный спрос.</p>`)
 ],practice:[number('ads','Дополнительный спрос 200 ед., свободная мощность 80 ед., вклад единицы 400 ₽, реклама 25 000 ₽. Прирост прибыли без расширения, ₽?',7000,'Реализуем только 80 ед.: 80 × 400 − 25 000 = 7 000 ₽.'),number('payback','Оборудование стоит 2 400 000 ₽ и даёт 120 000 ₽ дополнительного месячного потока. Простая окупаемость, месяцев?',20,'2 400 000 / 120 000 = 20 месяцев; не учтены дисконтирование и потоки после окупаемости.')],sourceNote:'Темы недели 4: здравоохранение, операционные инициативы и инвестиции в процесс.'
},
{
 id:'week05-procurement',week:5,title:'Цепочка поставок и закупки',description:'Различим интеграцию, аутсорсинг и офшоринг; сравним поставщиков по полной стоимости.',minutes:23,visual:'operations',goals:['Классифицировать решения о границах компании','Выбирать показатели закупок и рассчитывать эффект'],
 sections:[
 sec('chain','Как устроены природные ресурсы',S`<p>В нефтегазовой цепочке upstream отвечает за разведку и добычу, midstream — за транспортировку и хранение, downstream — за переработку и продажу конечного продукта. В горнодобывающей отрасли логика похожа: извлечь сырьё, подготовить и переработать, доставить покупателю. На каждом этапе разные затраты, ограничения и риски.</p><p>Вертикальная интеграция объединяет последовательные звенья: добывающая компания владеет переработкой. Горизонтальная — объединяет компании на одном звене, например две добывающие компании. Согласование планов с независимым поставщиком тоже интегрирует цепочку организационно, но не обязательно через собственность.</p>`),
 sec('boundaries','Две оси решения',S`<p>Аутсорсинг означает, что работу выполняет внешняя организация. Офшоринг означает, что работа перенесена за границу. Это две независимые оси: собственный зарубежный завод — офшорные внутренние операции; внешний зарубежный подрядчик — офшорный аутсорсинг; местный подрядчик — внутренний по географии аутсорсинг.</p><p>Выигрыш в цене может сопровождаться потерей контроля, длинным сроком поставки, зависимостью от партнёра и дополнительной потребностью в запасе. Передавать функцию следует после оценки полной стоимости и стратегической роли, а не только ставки за час.</p>`),
 sec('process','Четыре шага закупки',S`<p>Сначала опиши бизнес-потребность и требования к качеству. Затем собери сравнимые предложения, проверь поставщиков и условия. После выбора оформи договор с ценой, сроком, ответственностью и приёмкой. В конце проверь фактическую поставку, расчёты и документы. Изменения требований должны попадать в стоимость и план, иначе сравнение потеряет смысл.</p><p>Поставщик A предлагает деталь за 100 ₽, доставка 10 ₽, ожидаемая стоимость дефектов 5 ₽. Поставщик B просит 108 ₽, доставка 3 ₽, дефекты 1 ₽. Полная ожидаемая стоимость A — 115 ₽, B — 112 ₽. При 10 000 деталей B экономит 30 000 ₽, хотя его базовая цена выше.</p>`),
 sec('kpis','КПЭ не должны противоречить цели',S`<p>Cost reduction — снижение фактических сопоставимых затрат; cost avoidance — предотвращённый рост относительно явного альтернативного сценария. Эти показатели нельзя незаметно складывать. Доля управляемых закупок показывает охват процессом; defect rate — долю дефектных единиц; on-time/in-full — поставку вовремя и полностью; lead time — длительность ожидания.</p><p>Если улучшение закупок стоит 80 000 ₽ и даёт валовую экономию 200 000 ₽, чистая выгода 120 000 ₽. ROI = (200 000 − 80 000) / 80 000 = 150%. В формуле надо пояснить, включены ли затраты проекта уже в слове «экономия»: иначе расходы вычтутся дважды.</p>`),
 sec('tradeoff','Запас против устойчивости',S`<p>Just-in-Time сокращает запасы за счёт согласованной частой поставки. Но ненадёжный срок и критичный компонент могут оправдывать страховой запас и второго поставщика. Снижение закупочной цены большой партией может увеличить замороженные деньги, хранение, списания и риск устаревания.</p><p>Полезный вывод называет баланс: цена, качество, срок, запас и вероятность остановки. Для чувствительности измени цену брака и срок поставки; проверь, сохраняется ли выбор. Если различие в ожидаемой стоимости мало, надёжность и гибкость могут перевесить небольшую экономию.</p>`)
 ],practice:[number('tco','Цена детали 250 ₽, доставка 20 ₽, ожидаемые потери брака 15 ₽. Полная ожидаемая стоимость единицы, ₽?',285,'250 + 20 + 15 = 285 ₽. К цене прибавляем доставку и ожидаемые потери: это полная стоимость получения пригодной единицы.'),choice('integration','Производитель покупает своего поставщика сырья. Какой вид интеграции?', 'vertical',[['vertical','Вертикальная'],['horizontal','Горизонтальная'],['outsourcing','Аутсорсинг']],'Компания получает контроль над соседним звеном цепочки создания стоимости, поэтому интеграция вертикальная.')],sourceNote:'Темы недели 5: природные ресурсы, интеграция цепочки и закупки.'
},
{
 id:'week05-inventory',week:5,title:'Запасы: EOQ, точка заказа и списания',description:'Найдём размер партии и момент заказа, не смешивая физическую выдачу с оценкой себестоимости.',minutes:30,visual:'operations',goals:['Посчитать EOQ и ROP в согласованных единицах','Различать FIFO, FEFO, LIFO и среднюю стоимость'],
 sections:[
 sec('balance','Почему запас одновременно полезен и дорог',S`<p>Запас защищает от перебоев и позволяет закупать партиями, но требует денег, площади и контроля срока годности. Циклический запас нужен между поставками; страховой — для неопределённости спроса или срока. Размер партии отвечает на вопрос «сколько заказать», точка заказа — «когда».</p><p>Оборачиваемость запасов в денежной форме обычно равна себестоимости реализованных товаров за период, делённой на средний запас по себестоимости. При годовой себестоимости 2 400 000 ₽ и среднем запасе 400 000 ₽ это 6 оборотов в год. Средний срок хранения по модели = 365 / 6 ≈ 60,8 дня. Сравнивать выручку с запасом по себестоимости без оговорки нельзя.</p>`),
 sec('eoq','Экономичный размер заказа',S`<p>Пусть годовой спрос D = 12 000 единиц, оформление одной поставки S = 1 000 ₽, хранение единицы H = 240 ₽ в год. При постоянном спросе, мгновенном пополнении и отсутствии дефицита переменная часть годовых затрат равна DS/Q + HQ/2. Первая часть уменьшается при росте партии, вторая увеличивается.</p><div data-math="Q^*=\sqrt{\frac{2DS}{H}}=\sqrt{\frac{2\cdot12000\cdot1000}{240}}\approx316{,}23"></div><p>Около 316 единиц в заказе; примерно 37,95 поставки в год. Затраты заказа и хранения в непрерывном оптимуме равны примерно 37 947 ₽ каждая, суммарно 75 895 ₽. Постоянная закупочная стоимость не влияет на оптимум, пока цена единицы одинакова для всех партий.</p>`),
 sec('rop','Момент нового заказа',S`<p>Средний дневной спрос d = 40 единиц, срок поставки L = 5 дней, страховой запас SS = 60 единиц. За время ожидания уйдёт 200 единиц. Значит, ROP = dL + SS = 260 единиц. Заказ размещается по позиции запаса: остаток плюс уже заказанное минус неудовлетворённые заказы, если модель учитывает их.</p><div data-math="ROP=dL+SS"></div><p>EOQ и ROP не взаимозаменяемы: при достижении 260 единиц размещаем заказ примерно на 316. Не выбирай страховой запас произвольно в реальном проекте: он зависит от разброса спроса, lead time и целевого уровня сервиса. Когда разброс неизвестен, отметь, что SS — входное предположение.</p>`),
 sec('valuation','Физическая очередь и учётная оценка',S`<p>На склад поступили 10 единиц по 100 ₽ и 10 по 120 ₽, продано 12. При FIFO себестоимость = 10 × 100 + 2 × 120 = 1 240 ₽, остаток 8 × 120 = 960 ₽. При LIFO как учебном сравнении = 10 × 120 + 2 × 100 = 1 400 ₽, остаток 800 ₽. Средневзвешенная стоимость = 110 ₽/ед., себестоимость 1 320 ₽, остаток 880 ₽.</p><p>Каждый метод распределяет одни и те же 2 200 ₽ между продажей и остатком. Это не разные денежные закупки. Для скоропортящегося товара физически важен FEFO — первым выдать то, у чего раньше истекает срок. FIFO означает первым пришёл — первым ушёл; дата прихода и срок годности не всегда совпадают. LIFO здесь нужен для понимания расчёта, его допустимость в отчётности зависит от стандарта.</p>`),
 sec('abc','Приоритеты и ограничения модели',S`<p>ABC-анализ ранжирует позиции по годовому потреблению в деньгах: количество × стоимость. Категория A обычно содержит небольшое число особенно значимых позиций; границы групп задаются как правило анализа, а не как закон природы. Дорогая редкая деталь и дешёвая массовая деталь могут иметь одинаковый годовой вес, но разную критичность.</p><p>EOQ надо сравнивать с календарной поставкой на одном горизонте и с теми же затратами. Ограничения партии, срока годности, вместимости транспорта, сезонности и скидок могут изменить решение. После внедрения отслеживай списания, дефицит, сервис, запас в днях и полную стоимость, а не только уменьшение средней партии.</p>`)
 ],practice:[number('eoq','D = 10 000 ед./год, S = 400 ₽/заказ, H = 80 ₽/(ед.·год). EOQ, единиц? Округли до сотых.',316.23,'Корень из 2 × 10 000 × 400 / 80 = корень из 100 000 = 316,23.',.005001),number('rop','Спрос 30 ед./день, поставка 4 дня, страховой запас 50 ед. ROP, единиц?',170,'30 × 4 + 50 = 170 единиц. Запас должен покрыть спрос за четыре дня ожидания и оставить страховой буфер.')],sourceNote:'Темы недели 5 и операционной практики: закупочные партии, запас и его оценка.'
},
{
 id:'week05-production-plan',week:5,title:'Оптимальный производственный план',description:'Распределим дефицитные часы, затем запишем задачу с несколькими ограничениями.',minutes:32,visual:'operations',goals:['Ранжировать продукты по вкладу на ограниченный ресурс','Построить целевую функцию и ограничения для Solver'],
 sections:[
 sec('objective','Выбираем цель, а не самый дорогой продукт',S`<p>Когда ресурсов достаточно, компания может выпускать всё, на что есть прибыльный спрос. При дефиците часов надо сравнивать вклад на час узкого места. Цена единицы, процент маржи и абсолютный вклад отвечают разным вопросам.</p><p>В обычной модели contribution = цена − релевантные переменные затраты. В throughput accounting часто вычитаются только прямые материалы, а труд и прочие расходы считаются постоянными на коротком горизонте. Выбери одну трактовку и не смешивай её строки с другой. Здесь первый пример использует все переменные затраты.</p>`),
 sec('one-resource','Один ограниченный ресурс: пошагово',S`<p>Продукт A продаётся за 100 ₽, переменные затраты 60 ₽, нужен 1 час; спрос 80 единиц. Продукт B продаётся за 90 ₽, затраты 60 ₽, нужно 0,5 часа; спрос 100 единиц. Доступно 100 часов.</p><div class="table-wrap"><table><thead><tr><th>Продукт</th><th>Вклад/ед.</th><th>Часы/ед.</th><th>Вклад/час</th></tr></thead><tbody><tr><td>A</td><td>40 ₽</td><td>1</td><td>40 ₽</td></tr><tr><td>B</td><td>30 ₽</td><td>0,5</td><td>60 ₽</td></tr></tbody></table></div><p>Сначала выпускаем весь спрос B: 100 единиц занимают 50 часов и дают 3 000 ₽. Остаток 50 часов отдаём A: 50 единиц и 2 000 ₽. Итоговый вклад 5 000 ₽. План «сначала A с большим вкладом единицы» дал бы A = 80, B = 40 и всего 4 400 ₽.</p>`),
 sec('linear','Несколько ресурсов: модель целиком',S`<p>Простое ранжирование не гарантирует оптимум при нескольких одновременно дефицитных ресурсах. Для другого учебного примера x и y — объёмы двух товаров. Вклад единицы 40 и 30 ₽. Ограничения станка: 2x + y ≤ 100 часов; упаковки: x + y ≤ 70 часов; x, y ≥ 0.</p><div data-math="\max\ 40x+30y\quad\text{при}\quad 2x+y\le100,\ x+y\le70,\ x,y\ge0"></div><p>На пересечении двух ограничений x = 30, y = 40, вклад 2 400 ₽. Граничные вершины (0; 70) дают 2 100 ₽, (50; 0) — 2 000 ₽, (0; 0) — 0. Значит, найденная вершина оптимальна. Проверка всех ограничений обязательна: красивое значение целевой функции не делает план допустимым.</p>`),
 sec('excel','Как перенести в Excel',S`<p>Сделай отдельные изменяемые ячейки количеств. Целевая ячейка — SUMPRODUCT количеств и вкладов. Для каждого ресурса другая SUMPRODUCT считает потребление; справа стоит доступный лимит. В Solver максимизируй цель, изменяя количества, добавь ограничения ресурсов, спроса и неотрицательности. Для линейной модели подходит Simplex LP.</p><p>Если количество неделимо, задай целочисленные переменные. Округление непрерывного оптимума может нарушить ограничения и не дать лучшего целого плана. Если обязательства перед клиентом требуют минимального выпуска, добавь нижнюю границу. Постоянные расходы одинаковых вариантов не меняют оптимальный план, но вычитаются при расчёте итоговой прибыли.</p>`),
 sec('throughput','Пропускная способность и стоимость дефицита',S`<p>Для throughput accounting товар стоит 120 ₽, материалы 50 ₽, час узкого места на единицу 0,5. Throughput на единицу = 70 ₽, на час = 140 ₽. Если все операционные расходы за период 60 000 ₽, а доступно 1 000 часов, стоимость часа = 60 ₽; TPAR = 140 / 60 ≈ 2,33. Это отношение скоростей, а не процент маржинальности.</p><p>Дополнительный час имеет ценность только если можно произвести и продать ещё товар и нет другого ограничения. Цена дефицитного часа ограничивает выгодную доплату за сверхурочные. При сравнении собственной обработки и 3PL учитывай, какие часы реально освобождает подрядчик на всех этапах, и избегай передачи дорогому подрядчику только из-за меньшей цены единицы.</p>`)
 ],practice:[number('priority','Вклад товара 84 ₽/ед., требуется 0,7 часа узкого места. Вклад на час, ₽?',120,'84 / 0,7 = 120 ₽ на час дефицитного ресурса.'),number('lp','Для модели max 40x+30y при 2x+y≤100 и x+y≤70 оптимум x=30,y=40. Целевой вклад, ₽?',2400,'40 × 30 + 30 × 40 = 2 400 ₽; обе ресурсные границы выполнены с равенством.')],sourceNote:'Темы недели 5 и контрольной практики: ограниченные ресурсы, Solver и throughput.'
},
{
 id:'week06-production-data',week:6,title:'Производственные данные и выбор топлива',description:'Очистим единицы и группы, посчитаем целые рейсы и сравним сценарии прибыли.',minutes:32,visual:'operations',goals:['Не путать среднюю производительность со взвешенной','Считать транспорт по ограничениям времени и топлива'],
 sections:[
 sec('clean','Сначала привести данные к сопоставимому виду',S`<p>Таблица производства может соединять сотрудников, смены, участки, часы и тоннаж. Проверь идентификаторы, даты, повторы, пропуски и единицы. Если текстовые названия групп содержат лишние пробелы, одна смена распадётся в сводной на несколько. Персональные имена для учебного анализа не нужны: достаточно обезличенных идентификаторов.</p><p>Для каждого сотрудника или смены считай выпуск / отработанные часы. Если один произвёл 20 тонн за 2 часа, другой 30 тонн за 6 часов, среднее двух производительностей равно 7,5 т/ч, а общая производительность — 50 / 8 = 6,25 т/ч. Для результата предприятия нужно второе значение.</p>`),
 sec('diagnose','От наблюдения к причине',S`<p>Группируй по сменам и участкам: сумма тоннажа, сумма часов, число наблюдений, доля простоев. После сравнения общей производительности проверь состав работников, технику, маршрут, качество сырья и время простоя. Низкий результат ночной смены не доказывает низкую мотивацию её сотрудников.</p><p>Построй дерево: выпуск = работающие машины × рабочие часы × циклы в час × полезная нагрузка. Для каждого падения найди измеримый драйвер и альтернативное объяснение. Рекомендация должна улучшать именно найденное ограничение, а план проверки — отделять эффект изменения от сезонности и случайного колебания.</p>`),
 sec('truck','Целые рейсы: два независимых ограничения',S`<p>У учебного грузовика бак 180 л, расход 0,5 л/км, полный цикл 40 км, скорость 20 км/ч, рабочий день 16 часов. На цикл нужно 20 л и 2 часа. По топливу помещается floor(180/20) = 9 циклов, по времени floor(16/2) = 8. Выполним минимум: 8 циклов.</p><div data-math="n=\min\!\left(\left\lfloor\frac{B}{qL}\right\rfloor,\left\lfloor\frac{Tv}{L}\right\rfloor\right)"></div><p>B — бак, q — л/км, L — километры полного цикла, T — часы, v — скорость. Грузоподъёмность 12 т, загрузка 75%: за цикл 9 т, за день 72 т. При времени загрузки или обязательном перерыве добавь их в длительность цикла. Недостаток топлива на обратную дорогу запрещает начать следующий рейс.</p>`),
 sec('profit','От рейсов к годовой прибыли',S`<p>За 8 циклов пройдено 320 км, израсходовано 160 л. При цене топлива 70 ₽/л расход 11 200 ₽/день. Если вклад с тонны до топлива и обслуживания 500 ₽, то 72 × 500 = 36 000 ₽. Обслуживание 5 000 ₽/день, амортизация 1 000 ₽/день: учебная прибыль = 18 800 ₽/день.</p><p>Для 5 одинаковых машин и 300 рабочих дней это 28 200 000 ₽. Не умножай ещё раз расходы, если в исходных данных они уже даны на весь парк. Остаток топлива в баке не является ежедневным потреблением: после первого заполнения доливается израсходованное, а не каждый раз приобретается полный бак сверх остатка.</p>`),
 sec('scenario','Выбор меняется вместе с ценой продукции',S`<p>Новое топливо может быть дороже за литр, но уменьшать ремонт и увеличивать загрузку. Для каждого варианта заново вычисли число целых рейсов, тоннаж, выручку и затраты. В чувствительности меняй цену руды или вклад с тонны; не оставляй выручку прежней при изменившемся выпуске.</p><p>Если вариант A приносит за день 70p − 12 000 ₽, а B — 80p − 16 000 ₽, где p — вклад с тонны до этих затрат, равенство достигается при p = 400 ₽/т. Выше 400 выгоднее B, ниже — A. Такая граница информативнее одного «лучшего» варианта. Дополни вывод надёжностью поставок, температурным режимом и риском простоя.</p>`)
 ],practice:[number('cycles','Бак 150 л, расход 0,5 л/км, цикл 50 км. Времени хватает на 8 рейсов. Сколько полных циклов можно сделать без дозаправки?',6,'На цикл 25 л, по баку floor(150/25)=6, по времени 8. Минимум равен 6.'),number('weighted','Смена A: 120 т за 10 ч; смена B: 80 т за 20 ч. Общая производительность, т/ч? Округли до сотых.',6.67,'(120 + 80) / (10 + 20) = 6,6667 т/ч, после округления 6,67 т/ч; простое среднее 12 и 4 дало бы неверные 8.',.005001)],sourceNote:'Темы недели 6: анализ производительности, транспортные циклы и технологии.'
},
{
 id:'week07-product-team',week:7,title:'От бизнес-задачи к проверяемому продукту',description:'Согласуем продуктовую гипотезу, исследование и минимальные технические требования.',minutes:22,visual:'strategy',goals:['Связать предложение, метрику и требования','Подготовить краткое решение с рисками'],
 sections:[
 sec('question','Разные роли решают одну задачу',S`<p>В продуктовой команде продакт формулирует ценность и приоритет, аналитик проверяет предположения и считает эффект, разработка переводит решение в работающий процесс. Если каждая роль видит только собственный документ, можно качественно реализовать функцию, которая не решает нужную проблему.</p><p>Учебная ситуация: маркетплейс хочет создать раздел для дорогих товаров с высоким качеством обслуживания. Задача покупателя — получить подлинный товар с предсказуемой доставкой и удобным возвратом. Задача продавца — привлечь подходящих клиентов и сохранить экономику заказа. Обещание должно учитывать обе стороны.</p>`),
 sec('hypothesis','Формулируем гипотезу',S`<p>Рабочая гипотеза связывает изменение и результат: «Если показать подтверждение происхождения товара и точный срок доставки до оплаты, больше покупателей завершат оформление, при этом возвраты не вырастут». Предлагаемое решение основано на потребности, но причинность пока не доказана.</p><p>До разработки выясни частоту проблемы, её тяжесть, альтернативы и размер аудитории. Интервью дают объяснение поведения; данные воронки — масштаб потерь; тест — оценку эффекта. Не заменяй исследование ярким портретом клиента без наблюдений.</p>`),
 sec('metrics','Главная метрика и защитные показатели',S`<p>Пусть из 10 000 просмотров премиального товара 200 заканчиваются покупкой. Базовая конверсия 2%. Гипотеза роста до 2,4% означает 40 дополнительных заказов на тот же объём просмотров. При вкладе 2 000 ₽/заказ это 80 000 ₽ дополнительного вклада до расходов изменения.</p><p>Защитные метрики: доля возвратов, жалобы, опоздания, отмены продавцом, вклад заказа. Рост оформления при падении доли выкупленных заказов может не создать ценности. До теста зафиксируй период, критерий сравнения и то, какие клиенты попадают в знаменатель.</p>`),
 sec('requirements','Требования, которые можно проверить',S`<p>«Сделать надёжно» не проверяется. «До оплаты показать продавца, подтверждение происхождения, конечную цену, доступный интервал доставки и условия возврата» превращается в критерии приёмки. Для DBS дополнительно нужны остаток у продавца, принятие заказа, подтверждение передачи, статус доставки и канал решения проблем.</p><p>Минимальная схема заказа: покупатель оформляет → продавец подтверждает → товар отправлен → получен или возвращён. Для каждого перехода укажи владельца, событие данных и ошибочный сценарий. Проверяй недоступность товара, отмену, просрочку и дублирование события, а не только успешный путь.</p>`),
 sec('pitch','Короткое выступление по существу',S`<p>Хороший elevator pitch отвечает: у кого какая проблема; какое изменение предлагаем; что показывают данные; какой ожидается эффект; что может пойти не так; что проверим первым. Обещание «прибыль точно вырастет» заменяется условным выводом с расчётом и способом проверки.</p><p>Для первого запуска выбери небольшой ассортимент и ограниченный поток, обеспечь качество сервиса, затем сравни результат с базой. Этот урок — практика взаимодействия команды по материалам семинара, а не воспроизведение экзамена или обязательного формата итогового проекта.</p>`)
 ],practice:[number('increment','Просмотров 20 000. Конверсия выросла с 2% до 2,5%. Дополнительных заказов?',100,'20 000 × (0,025 − 0,02) = 100 дополнительных заказов.'),choice('guardrail','Какая метрика полезна как защита от роста некачественных заказов?', 'returns',[['returns','Доля возвратов'],['views','Число просмотров'],['features','Число новых функций']],'Конверсия может вырасти вместе с возвратами. Доля возвратов проверяет, сохранилось ли качество полученного результата.')],sourceNote:'Темы недели 7: продуктовая командная игра и модель доставки продавцом.'
},
{
 id:'week08-investments',week:8,title:'Инвестиции: денежные потоки и NPV',description:'Построим временную шкалу и приведём будущие поступления к одной дате.',minutes:30,visual:'finance',goals:['Отличать инвестицию и операционный поток','Посчитать NPV без смещения периода и двойного учёта'],
 sections:[
 sec('time','Деньги в разные даты не складываются напрямую',S`<p>Инвестиционное решение сравнивает сегодняшние затраты с будущими потоками. Ставка дисконтирования описывает требуемую доходность сопоставимого по риску варианта. В учебном расчёте ставка задана; её выбор не превращается в произвольную надбавку ради желаемого результата.</p><p>Будущая стоимость сегодняшней суммы PV через t периодов равна PV(1+r)^t. Обратная операция делит будущий CF на (1+r)^t. Ставка и период должны совпадать: годовую ставку нельзя без преобразования подставлять к месяцам. Номинальные потоки и номинальная ставка также должны быть согласованы.</p>`),
 sec('cashflows','Строим шкалу до формулы',S`<p>Учебное оборудование стоит 100 000 ₽ сегодня, в конце каждого из трёх лет приносит чистый дополнительный поток 45 000 ₽. В конце третьего года его можно продать за 10 000 ₽. Ставка 10% в год. Потоки: CF₀ = −100 000; CF₁ = 45 000; CF₂ = 45 000; CF₃ = 55 000 ₽.</p><p>Последний поток включает операционные деньги и продажу. Если подготовка оплачивается до открытия, поставь её на фактическую дату; платёж в нулевой момент не дисконтируется. Учитывай прирост оборотного капитала как отток и его высвобождение как приток, когда это задано. Амортизация сама по себе не платёж, хотя может менять налоговый поток.</p>`),
 sec('npv','Вычисление и интерпретация',S`<div data-math="NPV=\sum_{t=0}^{n}\frac{CF_t}{(1+r)^t}"></div><p>В примере приведённые поступления: 40 909,09; 37 190,08; 41 322,31 ₽. Их сумма 119 421,49 ₽. NPV = 19 421,49 ₽. Проект покрывает требуемую доходность 10% и создаёт ещё такую сегодняшнюю стоимость при заданных предпосылках.</p><p>NPV не означает, что на счёте появится 19 421,49 ₽ в конце третьего года. Это оценка на дату 0. Для независимого проекта NPV &gt; 0 поддерживает принятие. Если проекты взаимоисключающие и сопоставимы по риску и горизонту, приоритет создаваемой стоимости оценивается по NPV.</p>`),
 sec('spreadsheet','Таблица без ошибки на один год',S`<p>Сделай столбцы «период», «операционный поток», «инвестиции/продажа», «общий поток», «дисконтирующий множитель», «приведённый поток». Для каждого периода множитель = 1/(1+r)^t. Сумма последнего столбца должна совпасть с NPV.</p><p>Обычная функция Excel NPV дисконтирует первый переданный поток как конец первого периода. Поэтому при равных годовых интервалах используй NPV(r;CF1:CFn)+CF0. Если передать в диапазон ещё и CF0, вся шкала сдвинется. Для нерегулярных дат применяют расчёт по фактическим датам и соответствующую функцию XNPV.</p>`),
 sec('sensitivity','Что в действительности решает результат',S`<p>Проверь снижение загрузки, рост затрат, задержку запуска, уменьшение цены продажи объекта и увеличение ставки. Не называй прогноз точным: он условен. Увеличение ставки уменьшает NPV обычного проекта с одним начальным оттоком и последующими притоками; для необычных знаков потоков форма зависимости может быть сложнее.</p><p>Финансовое решение включает возможность профинансировать отрицательные ранние потоки. Положительная NPV не предотвращает кассовый разрыв. В выводе укажи главный драйвер, диапазон устойчивости и следующий шаг проверки спроса/сметы.</p>`)
 ],practice:[number('pv','Через год придут 110 000 ₽. Ставка 10% годовых. Текущая стоимость, ₽?',100000,'110 000 / 1,10 = 100 000 ₽.'),number('npv','CF0 = −100 000 ₽, CF1 = 60 000 ₽, CF2 = 60 000 ₽. r = 10%. NPV, ₽, до сотых?',4132.23,'−100 000 + 60 000 / 1,1 + 60 000 / 1,21 = 4 132,23 ₽.',.005001)],sourceNote:'Темы недели 8: инвестиционный анализ и временная стоимость денег.'
},
{
 id:'week08-investment-metrics',week:8,title:'IRR, PI, окупаемость и выбор проекта',description:'Посмотрим на проект с нескольких сторон и разберём границы каждого показателя.',minutes:28,visual:'finance',goals:['Правильно интерпретировать IRR и индекс рентабельности','Рассчитать простую и дисконтированную окупаемость'],
 sections:[
 sec('irr','IRR — корень уравнения',S`<p>IRR — ставка, при которой NPV = 0. Для проекта «−100 сегодня, +121 через два года» решаем −100 + 121/(1+IRR)² = 0, получаем IRR = 10% годовых. Это не 21% годовых: 21% — рост суммы за два года.</p><p>При обычном проекте с единственным начальным оттоком и последующими неотрицательными притоками сравнение IRR с требуемой ставкой согласовано со знаком NPV. Чередование знаков может создать несколько корней или ни одного. Ошибка функции IRR не означает автоматически невыгодность проекта.</p>`),
 sec('pi','Размер проекта и бюджет',S`<p>Для одного начального вложения I и последующих притоков индекс PI = PV будущих притоков / I = 1 + NPV/I. Если вложено 100 000 ₽, а NPV = 20 000 ₽, PI = 1,2. В записи PI = NPV/I получится другой показатель, 0,2; не смешивай определения.</p><p>PI помогает видеть стоимость на рубль вложений при дефиците бюджета. Но сортировка по PI не гарантирует лучший набор неделимых проектов. Взаимоисключающие проекты разного размера могут конфликтовать по IRR и NPV: высокий процент маленького проекта не обязательно создаёт больше денег для компании.</p>`),
 sec('payback','Простая окупаемость',S`<p>Инвестиция 100 000 ₽, годовые поступления 30 000, 40 000 и 50 000 ₽. Остаток к возврату после первого года 70 000, после второго 30 000 ₽. В третьем году поступает 50 000 ₽. Если деньги приходят равномерно в течение года, окупаемость = 2 + 30 000/50 000 = 2,6 года.</p><p>Если все потоки приходят только в конце года, точная дата возврата — конец третьего года. Дробное значение 2,6 — условная интерполяция, а не следствие годовой таблицы само по себе. Простая окупаемость не учитывает стоимость денег и игнорирует всё после даты возврата.</p>`),
 sec('discounted','Дисконтированная окупаемость',S`<p>При ставке 10% приведённые потоки того же проекта: 27 272,73; 33 057,85; 37 565,74 ₽. За три года сумма 97 896,32 ₽, то есть дисконтированная окупаемость на данном горизонте не достигнута, хотя простая достигнута. Нельзя объявлять её равной третьему году только по знаку недисконтированного остатка.</p><p>Для более длинной таблицы накапливай именно DCF вместе с начальным отрицательным вложением. Найди первый переход через ноль. При равномерном поступлении можно интерполировать долю периода; если поток дискретный, называй дату фактического поступления.</p>`),
 sec('eaa','Разные сроки и финальный выбор',S`<div data-math="EAA=NPV\cdot\frac{r}{1-(1+r)^{-n}}"></div><p>Эквивалентный годовой аннуитет переводит NPV в одинаковый ежегодный эквивалент за n лет. При r = 0 формула заменяется NPV/n. Сравнение повторяемых проектов разной длительности по EAA предполагает, что их можно возобновлять на сопоставимых условиях; для разового проекта эта предпосылка может не работать.</p><p>В решении покажи NPV как создание стоимости, IRR как ставку корня, PI как отношение стоимости к вложению и окупаемость как скорость возврата. Затем объясни расхождения и ограничения. Не голосуй большинством метрик: у них разные цели.</p>`)
 ],practice:[number('irr','Сегодня вложено 100 ₽, через 2 года получено 144 ₽, промежуточных потоков нет. IRR в процентах годовых?',20,'(144 / 100)^(1/2) − 1 = 0,20, то есть 20% годовых.'),number('pi','Первоначальное вложение 250 000 ₽, NPV = 50 000 ₽. PI по определению PV притоков / вложение?',1.2,'PI = 1 + 50 000 / 250 000 = 1,2.')],sourceNote:'Темы недели 8: критерии инвестиционных решений и их ограничения.'
},
{
 id:'week08-real-estate',week:8,title:'Недвижимость: проект, рынок и финансирование',description:'Сопоставим жизненный цикл объекта, источники денег и доходность без смешения масштабов.',minutes:24,visual:'finance',goals:['Различать первичный и вторичный рынки, аренду и продажу','Связать этап проекта с инвестиционными и финансовыми потоками'],
 sections:[
 sec('market','Что именно является рынком?',S`<p>Недвижимость включает жилые, офисные, торговые, складские и другие объекты. На первичном рынке покупается новый объект у создателя проекта, на вторичном — существующий у прежнего владельца. Стоимость всех объектов, объём строительства и объём инвестиционных сделок — разные величины; доли сегментов можно сравнивать только в одной базе.</p><p>Девелопер проходит выбор площадки, проектирование и согласования, финансирование, строительство, продажу или эксплуатацию. Владелец арендного объекта получает платежи во времени и несёт расходы содержания, простоя и обновления. Сроки и риски этих моделей отличаются даже при одинаковой цене объекта.</p>`),
 sec('finance','Откуда приходят средства',S`<p>Внутреннее финансирование — накопленные деньги и нераспределённая прибыль. Внешнее — долг или вклад собственников. Долг требует обслуживания и возврата, собственный капитал даёт право на остаточный результат и участие в риске. Новые заемные деньги не являются выручкой проекта.</p><p>Условный объект требует 10 млн ₽: собственники вносят 4 млн, кредитор — 6 млн. Балансовое финансирование не меняет физическую стоимость строительства. Если считаешь NPV всего проекта с потоком до обслуживания долга, используй соответствующую ставку и не вычитай проценты повторно. Если считаешь поток акционеру после долга, меняются и поток, и требуемая ставка.</p>`),
 sec('rent','Учебная модель аренды',S`<p>У здания 1 000 м², ставка 1 500 ₽/м² в месяц, средняя занятость 80%. Валовая арендная выручка = 1 000 × 1 500 × 0,8 × 12 = 14,4 млн ₽ в год. Если расходы эксплуатации без финансирования и амортизации 4,4 млн, операционный доход объекта 10 млн ₽.</p><p>Доходность на цену 100 млн ₽ в этой упрощённой модели 10%. Она не является IRR: здесь не заданы будущий рост, капвложения, продажа и сроки. При занятости 70% выручка 12,6 млн, а при тех же расходах доход 8,2 млн. Чувствительность к пустующей площади важна не меньше цены аренды.</p>`),
 sec('cycle','Цикл рынка и риски',S`<p>Рост спроса может повышать аренду и запуск новых строек. Долгое строительство приводит к тому, что новые площади выходят уже при изменившемся спросе; избыток снижает занятость и доход. Разные типы объектов реагируют на цикл неодинаково, поэтому нельзя переносить данные офисов на склады без проверки.</p><p>Для проекта проверь разрешения, стоимость и сроки стройки, условия долга, доступность инфраструктуры, спрос и альтернативное использование. Исторический рост цен не является гарантией. Названия реальных рынков в курсе дают отраслевой контекст; расчёт здесь основан на вымышленных данных.</p>`),
 sec('decision','Сравнение вариантов',S`<p>Сопоставь продажу объекта и сдачу в аренду на одной временной шкале с остаточной стоимостью. Приводи расходы и доходы к одинаковой дате и валюте. Не дели прибыль одного года на все вложения и не называй это полной инвестиционной оценкой.</p><p>Краткое заключение сообщает, какой вариант предпочтителен при заданной загрузке и ставке, какой запас прочности и какая предпосылка самая чувствительная. Если нет исходных данных для прогноза цены продажи или капитального ремонта, это явный пробел модели, а не повод принять нулевые значения без оговорки.</p>`)
 ],practice:[number('rent','Площадь 500 м², аренда 1 000 ₽/м² в месяц, занятость 90%. Годовая арендная выручка, ₽?',5400000,'500 × 1 000 × 0,9 × 12 = 5 400 000 ₽.'),choice('debt','Полученный банковский кредит в модели проекта — это…','financing',[['revenue','Выручка от покупателей'],['financing','Финансовый приток'],['profit','Чистая прибыль']],'Кредит меняет денежные средства и обязательства, но не является доходом от продажи товара или услуги.')],sourceNote:'Темы недели 8: недвижимость, финансовые решения и источники финансирования.'
},
{
 id:'week09-statements',week:9,title:'Три формы отчётности и лестница прибыли',description:'Построим P&L, проверим баланс и объясним, почему прибыль не равна денежному потоку.',minutes:32,visual:'finance',goals:['Рассчитать уровни прибыли и маржи','Разделить операционную, инвестиционную и финансовую деятельность'],
 sections:[
 sec('forms','Снимок, результат и движение',S`<p>Баланс — снимок активов, обязательств и капитала на дату. P&L — доходы и расходы за период. Отчёт о движении денежных средств — реальные поступления и платежи за период. Дополнительно отчёт об изменениях капитала и примечания объясняют состав и изменения. Одна форма не заменяет другую.</p><div data-math="Assets=Liabilities+Equity"></div><p>Покупка оборудования за 1 млн ₽ уменьшает деньги и создаёт актив. В P&L обычно попадает амортизация по периодам использования, а не вся покупка сразу. Продажа в кредит может создать выручку и дебиторскую задолженность без денег на счёте в момент продажи.</p>`),
 sec('pnl','Один учебный P&L',S`<p>Выручка 10 млн ₽, себестоимость проданного 6 млн, операционные расходы без амортизации 1,5 млн, амортизация 0,5 млн, проценты 0,2 млн, учебная ставка налога 20% положительной прибыли до налога.</p><div class="table-wrap"><table><thead><tr><th>Строка</th><th>млн ₽</th><th>Расчёт</th></tr></thead><tbody><tr><td>Gross profit</td><td>4,00</td><td>10 − 6</td></tr><tr><td>EBITDA</td><td>2,50</td><td>4 − 1,5</td></tr><tr><td>EBIT</td><td>2,00</td><td>2,5 − 0,5</td></tr><tr><td>EBT</td><td>1,80</td><td>2 − 0,2</td></tr><tr><td>Налог</td><td>0,36</td><td>1,8 × 20%</td></tr><tr><td>Net income</td><td>1,44</td><td>1,8 − 0,36</td></tr></tbody></table></div><p>Обозначения — уровни одной лестницы, а не независимые денежные поступления. Амортизация могла уже попасть в себестоимость: тогда нельзя вычитать её второй раз. Перед расчётом проверь классификацию исходных расходов.</p>`),
 sec('margins','Маржи, прогноз и единицы',S`<p>Валовая маржа примера 4/10 = 40%, EBITDA margin = 25%, EBIT margin = 20%, чистая маржа = 14,4%. Каждая делит соответствующий уровень прибыли на выручку того же периода. Наценка товара не является чистой маржой компании.</p><p>Если выручка будущего года 11 млн ₽ и EBIT margin по отдельному допущению останется 20%, EBIT = 2,2 млн ₽. Это прогноз через отношение, а не доказательство неизменности затрат. Приводи миллиарды и миллионы к одной единице до суммирования. Месячная аренда умножается на число месяцев работы, годовая зарплата повторно на 12 не умножается.</p>`),
 sec('cash','Почему деньги отличаются',S`<p>Операционная деятельность — основная работа; инвестиционная — покупка и продажа долгосрочных активов; финансовая — займы, их возврат и операции с собственниками. Прибыль 1,44 млн ₽ может сопровождаться низким денежным потоком, если выросла дебиторская задолженность или запас.</p><p>Упрощённый мост: к чистой прибыли прибавь неденежную амортизацию, вычти увеличение оборотного капитала и капитальные вложения, отдельно согласуй проценты и финансирование с выбранным определением потока. Этот мост зависит от цели модели; EBITDA сама по себе не равна свободному денежному потоку.</p>`),
 sec('ratios','Доходность и рыночные показатели',S`<p>ROA = чистая прибыль / средние активы, ROE = чистая прибыль / средний капитал. Если есть начало и конец года, средняя база обычно = (начало + конец)/2. Когда доступна только одна дата, используй её лишь как явно упрощённую оценку.</p><p>Капитализация = цена акции × число акций; при двух классах акций сложи стоимости каждого класса. EPS = прибыль, относимая к соответствующим акционерам, / среднее число соответствующих акций. P/E сравнивает рыночную стоимость и прибыль, P/B — стоимость и балансовый капитал. Дивидендная доходность = дивиденд на акцию / цена; payout = общие дивиденды / прибыль. Отрицательная прибыль делает обычную трактовку P/E проблемной.</p>`)
 ],practice:[number('net','Выручка 1 000, COGS 600, OPEX без амортизации 150, D&A 50, проценты 20, учебный налог 20% положительной EBT. Чистая прибыль?',144,'Gross 400 → EBITDA 250 → EBIT 200 → EBT 180 → налог 36 → чистая прибыль 144.'),number('margin','EBIT = 240 000 ₽, выручка 1 200 000 ₽. EBIT margin в процентах?',20,'240 000 / 1 200 000 × 100 = 20%.')],sourceNote:'Темы недели 9 и финансовой практики: отчётность, прибыль и финансовые коэффициенты.'
},
{
 id:'week09-banking',week:9,title:'Банк: посредничество, резервы и коэффициенты',description:'Разберём баланс банка, процентный доход и показатели риска без подмены базы расчёта.',minutes:32,visual:'bank',goals:['Различать активные и пассивные банковские продукты','Рассчитать базовые показатели прибыли, риска и эффективности'],
 sections:[
 sec('intermediary','Что делает финансовый посредник',S`<p>Банк соединяет вкладчиков и заёмщиков, обеспечивает платежи, преобразует сроки и управляет риском. Биржа организует торговлю, депозитарий учитывает права на бумаги, страховая компания объединяет риски через взносы и выплаты. Название «финансовый институт» шире банков.</p><p>Для банка депозит клиента — обязательство, выданный кредит — актив. Для клиента роли обратные. Банк получает процент по кредиту и платит по привлечённым средствам; дополнительно зарабатывает комиссии за услуги. Лизинг финансирует использование актива, факторинг связан с денежными требованиями к покупателям. В платеже картой участвуют покупатель, продавец, банки и платёжная инфраструктура.</p>`),
 sec('balance','Баланс и P&L банка',S`<p>У учебного банка активы 1 000 млн ₽, обязательства 900 млн, капитал 100 млн. В активах 700 млн валовых кредитов, резерв обесценения 20 млн уменьшает их чистую стоимость до 680 млн. Капитал — не то же самое, что денежный запас для выдачи кредита.</p><p>За год процентные доходы 100 млн, процентные расходы 40 млн: чистый процентный доход 60 млн. Комиссионные доходы 20 млн и расходы 5 млн дают 15 млн чистых комиссий. Другие доходы 5 млн, операционные расходы 35 млн, расходы на резервы 10 млн: прибыль до налога 35 млн. При учебном налоге 20% чистая прибыль 28 млн.</p>`),
 sec('provisions','Резерв: запас и изменение',S`<p>Резерв — оценка ожидаемого обесценения, а не отдельный денежный мешок, который обязательно лежит на счёте. Если резерв вырос с 20 до 30 млн ₽, при прочих равных расход периода 10 млн. Если затем снизился до 24 млн, восстановление 6 млн увеличит результат. Для реальной отчётности нужны также списания и иные движения, поэтому изменение остатка не всегда равно расходу.</p><p>Валовой кредит 100 млн и резерв 8 млн дают чистый кредит 92 млн. Просрочка — другое понятие: часть долга не погашена вовремя. Заёмщик может ещё не иметь просрочки, но риск уже вырос и потребовал резерва.</p>`),
 sec('metrics','Согласованные базы показателей',S`<p>Пусть средние процентные активы 800 млн, средние валовые кредиты 650 млн, средние активы 950 млн, средний капитал 95 млн; конечные кредиты 700 млн, депозиты 800 млн. Тогда распространённая NIM на средние процентные активы = 60/800 = 7,5%; ROA = 28/950 ≈ 2,95%; ROE = 28/95 ≈ 29,47%; LDR = 700/800 = 87,5%.</p><p>В учебной банковской схеме курса NIM считают на средние валовые кредиты: 60/650 ≈ 9,23%, а Fee Margin, FM, = чистые комиссии / средние валовые кредиты = 15/650 ≈ 2,31%. Это другая база NIM, её нельзя незаметно заменить процентными активами. Операционный доход для CIR в схеме курса = 60+15 = 75 млн, CIR = 35/75 ≈ 46,67%. Расширенная база с прочими доходами дала бы 35/80 = 43,75%; для сравнения нужен одинаковый состав. Cost of Risk, COR = расход на резервы / средние валовые кредиты = 10/650 ≈ 1,54%. При просроченных кредитах 35 млн NPL = 35/700 = 5%. Provision Ratio в простой трактовке = резерв/валовые кредиты, а покрытие NPL = резерв/NPL — это разные коэффициенты.</p>`),
 sec('limits','Что показатели не говорят сами по себе',S`<p>FM здесь означает именно Fee Margin — комиссионную маржу. При общей кредитной базе NIM + FM − COR = (60+15−10)/650 = 10%; так виден регулярный результат до операционных расходов. Доля комиссионного дохода = 15/(60+15) = 20%. Cost-to-Assets = операционные расходы / средние активы = 35/950 ≈ 3,68%; сокращение CAR встречается и для этого коэффициента, и для достаточности капитала. «Рентабельность банка» без определения тоже не является одной универсальной формулой.</p><p>Достаточность капитала использует регуляторный капитал и активы, взвешенные по риску, а не просто капитал/активы баланса. Здесь мы не задаём действующие нормативные пороги. Высокая ROE может быть следствием высокого финансового рычага, высокий LDR — риска фондирования, низкий CIR — масштаба или недостатка инвестиций. Сравнивай банки с одинаковым определением показателей и периодом.</p>`)
 ],practice:[number('nim','Чистый процентный доход 36 млн ₽, средние процентные активы 600 млн ₽. NIM именно на этой базе в процентах?',6,'36 / 600 × 100 = 6%. В знаменателе именно средние процентные активы из условия, чтобы доход за период сопоставлялся с работающей базой.'),number('cir','Операционные расходы 45 млн ₽, операционный доход до резервов 100 млн ₽. CIR в процентах?',45,'45 / 100 × 100 = 45%. Резервы не следует автоматически включать в этот знаменатель или числитель.')],sourceNote:'Темы недели 9: финансовые посредники, банковская отчётность и показатели.'
},
{
 id:'week09-seasonality',week:9,title:'Сезонность и решение открыть объект',description:'Отделим неизбежные расходы от дополнительных и построим помесячные потоки гостиницы.',minutes:28,visual:'finance',goals:['Считать загрузку, номеро-ночи и релевантные затраты','Оценивать сезонный сценарий и ограниченный горизонт ROI'],
 sections:[
 sec('capacity','Помесячная модель вместо «среднего года»',S`<p>В сезонном бизнесе одинаковая годовая выручка может означать совершенно разный риск кассового разрыва. Для гостиницы сначала посчитай доступные номеро-ночи: номера × дни работы. Проданные номеро-ночи = доступные × загрузка. Выручка = проданные × средняя цена ночи. Загрузка должна лежать от 0 до 100%.</p><p>Учебный объект имеет 20 номеров; в 30-дневном месяце 600 доступных номеро-ночей. При загрузке 40% продано 240. Цена 5 000 ₽ даёт 1 200 000 ₽ выручки. При переменных затратах 1 500 ₽ на проданную ночь вклад = 840 000 ₽ до постоянных расходов.</p>`),
 sec('open-close','Открыться или остаться закрытым?',S`<p>В несезонный месяц постоянные неизбежные расходы охраны и аренды 300 000 ₽ платятся в любом случае. Открытие дополнительно требует 200 000 ₽ персонала и подготовки. Группа хочет купить 80 номеро-ночей по 4 000 ₽, переменные затраты 1 500 ₽. Дополнительный вклад = 80 × 2 500 = 200 000 ₽, ровно покрывает дополнительные расходы открытия.</p><p>Для сравнения «открыть/закрыть» общие 300 000 ₽ сокращаются: они не меняют выбор. Но в общей прибыли месяца они остаются. Если игнорировать их в годовом отчёте, результат будет завышен. При равенстве денег решение зависит от риска, качества сервиса и альтернативного использования времени.</p>`),
 sec('breakeven','Порог загрузки',S`<div data-math="N_{BE}=\frac{F_{incremental}}{P-v}"></div><p>При дополнительных расходах 180 000 ₽, цене 4 000 ₽ и переменных затратах 1 500 ₽ нужно 72 номеро-ночи. Из 600 доступных это 12% загрузки. Если у группы особые расходы на трансфер или питание, включи их в переменные либо отдельную дополнительную статью.</p><p>Для каждого месяца создай цену, дни, загрузку, проданные ночи, выручку, переменные и постоянные расходы. Проверка: число проданных ночей не выше вместимости. Округление требуется, если модель описывает конкретные целые ночи, а не ожидаемое среднее.</p>`),
 sec('roi','ROI, продажа и ограниченный горизонт',S`<p>ROI на выбранном горизонте надо определить явно. Учебная недисконтированная версия = (сумма чистых поступлений, включая продажу, − все вложения) / все вложения. Если за три года получено 9 млн ₽ операционных денег и 5 млн от продажи при вложениях 10 млн, ROI = 40%. Это совокупная доходность за три года, не 40% в год.</p><p>При одном изолированном годе «чистая прибыль / начальные инвестиции» тоже называют ROI, но такой коэффициент нельзя сравнивать с полной трёхлетней доходностью. Для инвестиционного выбора построй NPV по датам и включи терминальную стоимость. Потраченные раньше безвозвратные деньги не должны искажать новое решение, если их уже нельзя изменить.</p>`),
 sec('stress','Сценарии и новые обстоятельства',S`<p>Пересчитай модель при меньшей загрузке, росте затрат и задержке открытия. Если выяснились дополнительные обязательные работы, внеси их в соответствующий поток, а не только в словесный список рисков. Сравни продолжение с доступной альтернативой: остановка тоже может требовать расходов.</p><p>Для решения «принимать ли группу» используй только изменяемые потоки этого решения; для решения «стоило ли вкладываться в объект» — полную инвестиционную модель. Разделение этих двух вопросов помогает не отказаться от полезного заказа из-за старых уже понесённых расходов.</p>`)
 ],practice:[number('nights','15 номеров × 30 дней, загрузка 60%. Сколько проданных номеро-ночей?',270,'15 × 30 × 0,6 = 270 номеро-ночей.'),number('breakeven','Дополнительные расходы открытия 150 000 ₽, цена ночи 4 500 ₽, переменные затраты 2 000 ₽. Порог номеро-ночей?',60,'150 000 / (4 500 − 2 000) = 60 номеро-ночей.')],sourceNote:'Темы финансовой практики недель 8–9: гостиничный проект и сезонность.'
},
{
 id:'week10-logistics',week:10,title:'Логистика: спрос, субсидия и деловое обоснование',description:'Соберём P&L маршрута и аргументируем решение по материалам объединённой практики.',minutes:27,visual:'strategy',goals:['Проверить ограничение транспортной доступности','Рассчитать недостающий поток и объяснить решение'],
 sections:[
 sec('scope','Что есть в этом блоке',S`<p>Этот урок разбирает методы недели 10, которые представлены в объединённом финансовом задании. Отдельных лекции и семинара недели 10 в предоставленном основном наборе нет. Поэтому здесь есть учебный разбор логистической и финансовой модели, но не заявлено полное покрытие всей недели.</p><p>Туристический объект может иметь достаточное число номеров, но ограниченный поток посетителей из-за транспорта. Нельзя увеличить загрузку только заменой процента в таблице: проверь, сколько гостей реально могут приехать и когда. Спрос, вместимость транспорта и вместимость объекта совместно ограничивают продажи.</p>`),
 sec('route','Единицы маршрута',S`<p>Учебный маршрут выполняет 20 рейсов в месяц, в самолёте 50 мест, средняя загрузка 70%. Это 700 пассажиро-перелётов. Если статистика включает и прилёт, и вылет туриста, для оценки числа прибывших гостей потребуется разделить соответствующий двусторонний поток; не делай это автоматически без определения данных.</p><p>Выручка при билете 8 000 ₽ = 5,6 млн ₽. При переменных затратах 2 000 ₽ на пассажиро-перелёт и дополнительных расходах рейсов 3 млн ₽ вклад маршрута до общих расходов = 5,6 − 1,4 − 3 = 1,2 млн ₽. Число мест, рейсы, направления и период должны быть явно названы.</p>`),
 sec('pnl','От маршрута до чистой прибыли',S`<p>Для другой учебной модели выручка 12 млн ₽, COGS 7 млн, OPEX без амортизации 2 млн, амортизация 1 млн, проценты 0,5 млн. Тогда gross profit 5 млн, EBITDA 3 млн, EBIT 2 млн, EBT 1,5 млн. При условной ставке налога 20% чистая прибыль 1,2 млн ₽, чистая маржа 10%.</p><p>Дотация может относиться к отдельным рейсам, местам или общему результату: её учёт зависит от условий модели. Сначала посчитай вариант без поддержки и явно опиши механизм субсидии. Не добавляй одну и ту же сумму одновременно к выручке и к финансированию без основания.</p>`),
 sec('subsidy','Сколько поддержки действительно нужно?',S`<p>Дополнительный рейс приносит 300 000 ₽ выручки и требует 350 000 ₽ дополнительных денежных затрат. Для нулевого дополнительного результата нужна поддержка 50 000 ₽ на рейс. Если цель — ещё 20 000 ₽ дополнительного результата, требуется 70 000 ₽. Нельзя компенсировать всю среднюю себестоимость компании, когда решение меняет только часть затрат.</p><p>Проверь, не заберёт ли новый рейс пассажиров с существующих: тогда часть новой выручки лишь перемещается. Если поддержка должна сохранить доступную цену, сравни варианты количества рейсов, тарифа и загрузки. Назови возможные эффекты для гостиницы отдельно от прибыли перевозчика.</p>`),
 sec('memo','Как написать убедительное обращение',S`<p>Структура короткого делового письма: приветствие и контекст; конкретная проблема; предлагаемое решение; требуемая поддержка; расчёт эффекта и условий; риски и контроль; завершение. Приложи понятную модель с единицами и предпосылками. Не выдавай желаемую загрузку за доказанный спрос.</p><p>Аргумент «направление важно» усиливается измеримыми данными: число дополнительно доступных мест, ожидаемые посетители, размер дефицита и способ проверки результата. Обещай то, что можно наблюдать и пересмотреть. Эта практика не является включением общей «Пробной сессии» платформы и не задаёт вымышленный экзаменационный формат.</p>`)
 ],practice:[number('support','Дополнительная выручка рейса 420 000 ₽, дополнительные затраты 470 000 ₽. Минимальная поддержка до нулевого результата, ₽?',50000,'470 000 − 420 000 = 50 000 ₽. Это минимум при заданных предпосылках.'),number('seats','12 рейсов по 60 мест, загрузка 75%. Сколько пассажиро-перелётов за период?',540,'12 × 60 × 0,75 = 540 пассажиро-перелётов. Это ещё не обязательно число уникальных туристов.')],sourceNote:'Методы недели 10 из объединённого финансового задания: логистика и обоснование решения.'
},{
 id:'week06-model-workshop',week:6,title:'Собираем модель для ДЗ и контрольной',description:'Отработаем таблицы категорий и минимизацию затрат со сверхурочными на своих данных.',minutes:32,visual:'operations',goals:['Связать исходные строки и итоговые формулы','Записать допустимый план обязательных заказов без готовой сдачи'],
 sections:[
 sec('purpose','Отработка методов, а не чужих ответов',S`<p>В материалах есть шаблон контрольной с операциями и юнит-экономикой. Здесь отрабатываются соответствующие методы на других числах; баллы, длительность и полная структура реальной проверки не воспроизводятся. Полезный результат — модель, которую можно объяснить по каждой строке.</p><p>Начни с листа допущений: что означает строка, какой период, какие единицы, какие расходы меняются. Входные числа держи отдельно от расчётов. Подпиши формулы и добавь проверки сумм, ограничений и диапазонов. Цвет помогает ориентироваться, но не заменяет подпись.</p>`),
 sec('category-model','Категории, поиск и суммирование',S`<p>Пусть строки продаж содержат категорию, количество и цену. Выручка строки = количество × цена. Для категории суммируй её выручку через SUMIF/SUMIFS либо сводную; ставку маржи подтяни из отдельного справочника через XLOOKUP или точный VLOOKUP. В русской локали названия функций и разделители могут отличаться. Ключ категории должен совпадать после очистки пробелов.</p><p>Для двух строк одной категории: 3 единицы по 100 ₽ и 2 по 150 ₽, выручка = 600 ₽. При марже 30% вклад = 180 ₽. Средняя цена единицы 600/5 = 120 ₽. Если строки принадлежат одному чеку, средний чек равен 600 ₽, а не 300 ₽ и не 120 ₽. Считать количество строк количеством чеков нельзя.</p>`),
 sec('scores','Оценки клиентов и сценарий удержания',S`<p>Опросы анализируй по определённому правилу. При NPS доля критиков включает оценки 0–6, промоутеров — 9–10; при CSAT положительный диапазон задаётся отдельно. Если легенда связывает уход с оценкой ниже особого порога, churn = число клиентов в этом диапазоне / число клиентов в соответствующей категории. Это модель конкретного условия, а не стандартная формула из NPS.</p><p>После изменения оценок сначала преобразуй исходные оценки, затем заново посчитай группы и churn. «Повысить NPS в 1,5 раза» и «умножить каждую оценку на 1,5» дают разные результаты. Если преобразованная оценка выходит за пределы шкалы, правило ограничения должно быть явно задано: нельзя молча заменить его удобным. При неоднозначности покажи, какая интерпретация использована, и сравни сценарии.</p>`),
 sec('mandatory-orders','Обязательные заказы и сверхурочные',S`<p>Нужно выполнить 80 заказов A и 40 заказов B. Внутренняя обработка требует 0,5 и 1 час узкого места соответственно; обычная мощность 60 часов. Сверхурочно разрешено до 10 часов по 500 ₽/час. Передача подрядчику стоит дополнительно к собственной переменной обработке 400 ₽ для A и 1 200 ₽ для B. Переданный заказ целиком снимает нужду в его внутренней обработке.</p><p>Полная внутренняя потребность = 80×0,5 + 40×1 = 80 ч, дефицит 20. Переплата подрядчику на освобождённый час: A — 400/0,5 = 800 ₽/ч, B — 1 200/1 = 1 200 ₽/ч. Поэтому сначала используем 10 сверхурочных часов за 5 000 ₽, затем освобождаем 10 часов передачей 20 заказов A за 8 000 ₽ переплаты. Всего дополнительных расходов 13 000 ₽.</p><p>Здесь обычные переменные расходы считаются общей базой всех вариантов, а тариф подрядчика дан как переплата к ней. Если тариф дан полным, сначала вычти избегаемую собственную стоимость. Проверь также остальные этапы: если они ограничивают план, сравнение только одного часа недостаточно.</p>`),
 sec('solver-min','Полная запись задачи и проверка',S`<p>Пусть a и b — числа переданных подрядчику заказов, h — сверхурочные часы. Минимизируем 400a + 1 200b + 500h. Ограничение времени: 0,5(80−a) + (40−b) ≤ 60+h. Дополнительно 0≤a≤80, 0≤b≤40, 0≤h≤10; a и b целые. Для найденного плана a=20, b=0, h=10: внутренние 60 заказов A и 40 B используют 70 часов, ровно доступные 60+10.</p><p>При нескольких этапах добавь отдельное ограничение времени для каждого. Обязательные объёмы связываются равенством «свои + подрядчик = заказ», чтобы оптимизатор не снизил затраты отказом от клиентов. Для линейной модели используй Simplex LP и целочисленные ограничения там, где единицы неделимы.</p>`),
 sec('capacity-policy','Постоянная мощность или следование спросу?',S`<p>Level capacity поддерживает стабильную мощность и поглощает колебания запасом, очередью или недозагрузкой. Chase demand меняет смены, сверхурочные, временный персонал и подрядчиков под спрос. Demand management пытается перенести сам спрос: бронирование, тарифы непикового времени, акции в слабый сезон.</p><p>Выбор зависит от возможности хранить продукт, качества, стоимости изменения штата и обещаний клиенту. Для скоропортящегося товара запас не всегда решает пик; для услуги с фиксированным числом мест полезно управление временем спроса. Финальный вывод должен назвать выполнимый план, стоимость, ограничение и риск качества.</p>`)
 ],practice:[number('overtime','Для обязательных заказов нужно 90 ч, обычная мощность 70 ч, сверхурочные 10 ч. Сколько ещё часов нужно освободить подрядчиком?',10,'90 − 70 − 10 = 10 часов; затем выбирается допустимый и выгодный состав переданных заказов.'),number('revenue','В одном чеке 4 товара по 80 ₽ и 2 по 140 ₽. Сумма чека, ₽?',600,'4 × 80 + 2 × 140 = 600 ₽. Количество товарных строк не меняет число чеков.')],sourceNote:'Отработка методов блока 1–2 и шаблона контрольной на авторских данных.'
},
{
 id:'week04-rd-pipeline',week:4,title:'R&D: молекулярный пайплайн и отбор',description:'Построим последовательные фильтры, посчитаем доли прошедших и обоснуем исследование рынков.',minutes:30,visual:'operations',goals:['Различать взвешенное среднее, последний тест и условие всех тестов','Собрать воронку кандидатов без потери исходной базы'],
 sections:[
 sec('stages','Зачем бизнесу понимать этапы исследования',S`<p>Фармацевтический R&D — последовательность исследований с затратами, временем и неопределённостью. Ранний отбор сокращает множество кандидатов, последующие стадии проверяют новые вопросы. В лаборатории, исследовании с участием людей и регуляторном рассмотрении различаются цели и доказательства.</p><p>В типичном клиническом пути фаза I прежде всего изучает безопасность и дозирование, фаза II — действие и побочные эффекты у пациентов, фаза III — подтверждающие данные в более широких исследованиях, а после допуска продолжается наблюдение. Схему и переходы объясняет <a href="https://www.fda.gov/patients/drug-development-process/step-3-clinical-research" target="_blank" rel="noopener">FDA: клинические исследования</a>. Учебные баллы и пороги в таблице не являются реальными нормативами допуска лекарства.</p>`),
 sec('synthetic','Три правила нельзя заменять одним средним',S`<p>Рассмотрим только синтетические кандидаты A, B, C. В первом этапе три теста имеют веса 20%, 30%, 50%, порог 70%. У A результаты 60%, 70%, 80%: взвешенный балл = 0,2×0,60 + 0,3×0,70 + 0,5×0,80 = 73%, поэтому он проходит. Простое среднее дало бы 70%, то есть другой показатель.</p><p>На этапе доработки может действовать правило «проверить только последнюю версию»: прежние результаты относятся к прежним вариантам и не усредняются с новым. На этапе устойчивости может потребоваться, чтобы каждый из нескольких тестов был выше порога. Тогда проверяется логическое AND, либо минимум результатов, а не среднее.</p>`),
 sec('filters','Пайплайн как накопительное условие',S`<p>Для каждой молекулы сохрани исходный ID как текст, чтобы длинные идентификаторы не округлялись. Подтяни результаты точным поиском. Затем создай флаги: прошёл первый этап; прошёл второй с учётом первого; прошёл третий с учётом предыдущих. Кандидат, проваливший ранний обязательный этап, не может вернуться только потому, что поздняя оценка высокая.</p><p>В Excel взвешенное среднее считается SUMPRODUCT результатов и весов; флаг — IF/AND; число — COUNTIF/COUNTIFS или сумма флагов. Диапазоны фиксируются там, где формула копируется вниз. Ошибку поиска сначала выясни: пустая ячейка, неизвестный ID и нулевой результат — разные состояния. Скрывать их все как ноль опасно.</p>`),
 sec('counts','Процент от исходного набора или от прошлого этапа?',S`<p>Из 1 000 открытых кандидатов первый фильтр оставил 200, второй — 40, финальный — 8. Накопительные доли от всех открытых равны 20%, 4%, 0,8%. Переходы между соседними этапами равны 20%, 20%, 20%. Они отвечают разным вопросам, поэтому в таблице назови знаменатель.</p><p>Если финал требует обоих результатов не ниже заданного порога, сначала проверь это условие, затем ранжируй прошедших по критерию из легенды. Нельзя компенсировать провал обязательного порога вторым высоким тестом. Если важнее последняя, более крупная выборка, это правило ранжирования применяется только после проверки допуска. Выбранный ID остаётся результатом частного файла, его не нужно публиковать в учебном конспекте.</p>`),
 sec('evidence','От таблицы до реального решения',S`<p>Реальный регулятор оценивает совокупность данных о качестве, безопасности и эффективности; спонсор подаёт соответствующее досье, возможны дополнительные запросы и проверки. Одного «процента успешности» недостаточно. Официальная отправная точка — <a href="https://www.fda.gov/drugs/development-approval-process-drugs" target="_blank" rel="noopener">FDA: разработка и одобрение лекарств</a>. Допуск в одной юрисдикции не следует автоматически переносить на другие рынки.</p><p>Для качества исследования важны сопоставимость групп, заранее выбранные исходы, контроль потерь наблюдения, рандомизация и ослепление там, где они применимы. Efficacy — результативность вмешательства в определённых условиях исследования; efficiency — соотношение результата и затраченных ресурсов. Низкая стоимость не доказывает результативность.</p>`),
 sec('markets','Как исследовать востребованность по странам',S`<p>Востребованность — не просто наибольшее население. Сопоставь распространённость заболевания, число диагностированных и потенциально подходящих пациентов, доступность существующей терапии, платёжный механизм и путь доступа. Частота редкого заболевания может заметно различаться между группами; нельзя переносить одну выборку на всю страну.</p><p>Сделай таблицу: страна, год, население нужной группы, распространённость с единицей, оценка числа пациентов, доля диагностики, источник, ограничение. Например, 4 случая на 100 000 в группе 5 млн человек дают 200 ожидаемых случаев до поправки на диагностику. Научные исследования, регистры и официальные отчёты лучше рекламного текста. Указывай ссылку, дату и применимость. Затем отдельно исследуй регуляторный доступ и канал — специалист, клиника, плательщик, дистрибьютор. Этот урок даёт метод, а не готовый выбор трёх стран без проверенной статистики.</p>`)
 ],practice:[number('weighted-test','Учебные результаты тестов 60%, 80%, 90%, веса 20%, 30%, 50%. Взвешенный результат в процентах?',81,'0,2×60 + 0,3×80 + 0,5×90 = 12 + 24 + 45 = 81%.'),number('pipeline-share','Из 2 000 исходных кандидатов к финалу осталось 6. Накопительная доля в процентах?',0.3,'6 / 2 000 × 100 = 0,3%. Знаменатель — исходный набор, а не число кандидатов предыдущей стадии.')],sourceNote:'Темы недели 4: R&D, молекулярный пайплайн и доказательное исследование рынка.'
}
];
